(window.STORIES=window.STORIES||[]).push(...[{"n": 99, "l": "الجزء 73 | نصر المسلمين في احد", "u": "https://www.facebook.com/groups/710210019782034/permalink/812767812859587/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الثالثة_والسبعون\n#نصر_المسلمين_في_أُحد\nاتكلمنا المرة إللي فاتت عن ترتيبات جيش المسلمين قبل بداية القتال، وشفنا إزاي كانوا متحمسين وروحهم المعنوية عالية،\nهنروح لمعسكر المشركين ونشوف ترتيباتهم كانت إيه هم كمان\nكان أبو سفيان قائد جيش المشركين في أحد،\nقسّم جيش المشركين لمَيْمنة ومَيْسرة وخلى قائد الميمنة خالد بن الوليد،\nوالميسرة قائدهم عكرمة بن أبي جهل، وجعل صفوان بن أمية قائد المشاة، أما الراية فكان يحملها بني عبد الدار،\nاحنا قلنا قبل كده إن الراية مهمة جدا، \nلأنها طول ماهي واقفة ده معناه إن الجيش لسه بقوته وبيقاتل، أما لو وقعت الراية فهي الهزيمة\nفكان المسؤول عن حمل الراية في جيش المشركين في غزوة بدر وكمان في غزوة أُحد هم بنو عبد الدار،\nأبو سفيان أراد إن يحمسّهم ويحفزهم عشان يبذلوا أقصى طاقة عندهم في الدفاع عن الراية فقال لهم:\nيا بني عبد الدار! \nانتم تركتم الراية تقع يوم بدر وحصل إللي حصل، يعني انتم مشاركين في الهزيمة إللي حصلت، \nفلو مش هتقدروا تدافعوا عن الراية النهاردة سيبوها من دلوقتي واحنا هنشوف حد تاني يكون أد المسؤولية دي\nطبعا بنو عبد الدار غضبوا وثارت حميّتهم، فقالوا لأبي سفيان:\nاحنا نسيب اللواء\nبكرة هتشوف وقت الحرب هنعمل إيه\nمش بس أبو سفيان إللي كان بيحمس المشركين، ده هند بنت عتبة زوجة أبي سفيان هي كمان والنساء إللي معاها كانوا بيشجعوا جيش المشركين على الحرب عن طريق إنشاد الشعر الحماسي، \nبس طبعا كلها حاجات دنيوية زائلة، ففي فرق بين إللي بيقاتل عشان شوية مكاسب في الدنيا وبين إللي بيقاتل عشان عايز جنة عرضها السماوات والأرض\nحاول أبو سفيان إنه يفكك صفوف المسلمين، فأرسل إلى الأنصار يقول لهم:\nاحنا مش عايزين نقاتلكم، علاقتنا بكم كويسة من زمان، فخلّوا بيننا وبين بني عمنا، يعني انتم ارجعوا وسيبوا أقاربنا من القرشيين نقاتلهم\nفطبعا الأنصار رفضوا كلام أبو سفيان وصمموا على قتال المشركين والدفاع عن رسول الله ﷺ،\nمين بقى كان مع المشركين في الغزوة دي\nأبو عامر الراهب إللي سماه رسول الله ﷺ الفاسق أبو حنظلة بن أبي عامر إللي تزوج قبل المعركة بيوم بابنة عبد الله بن أبي بن سلول إللي اتكلمنا عليهم المرة إللي فاتت \nأبو عامر الفاسق ده راح وقف أمام الانصار وقال لهم:\nيا معشر الأوس ! أنا أبو عامر، تعالوا قاتلوا معايا وسيبوا محمد\nفقالوا له: لا أنعم الله بك عينًا يافاسق\nدعوا عليه وقعدوا يشتموه\nفقال أبو عامر : قد أصاب قومي من بعد شر\nيعني قومي اتغيروا للأسوأ من بعد ما تركتهم\nأبو عامر ده أخذ مجموعة من المشركين وقعدوا يحَفُروا حُفَر في أرض أُحد عشان المسلمين يسقطوا فيها، \nواصطف الجيشين عشان يبدأوا القتال،\nلو أخذنا بالنا هنلاقي إن غزوة أحد بالنسبة للمسلمين أسهل من غزوة بدر\nلأن في غزوة أحد فقدت قريش معظم قاداتها، يعني مفيش حد من القادة الكبار غير أربعة تقريبا،\nبعكس في غزوة بدر كان قادة المشركين كلهم حاضرين،\nوالغزوة دي المسلمين عارفين بها من البداية فاستعدوا لها مضبوط،\nالمشركين جاءوا من مكة وهي مسافة بعيدة جدا حوالي  خمسمائة كيلو، فده لوحده إرهاق لجيش المشركين، بعكس المسلمين إللي خرجوا من المدينة لمنطقة أحد وهي قريبة جدا من المدينة كم كيلو متر بس،\nده غير إن الروح المعنوية للمسلمين عالية جدا بعكس المشركين إللي اتهزموا في بدر وحصلت لهم أزمات خلال السنة إللي فاتت دي كلها،\nأيوة عدد المسلمين أقل لكن أسباب النصر كلها مجتمعة في جيش المسلمين،\nده غير البشارة إللي رسول الله ﷺ بشّر بها المسلمين وهي إنهم لو صبروا وثبتوا الملائكة هتيجي تقاتل معاهم\nربنا قال:\n\"بَلَىٰ ۚ إِن تَصْبِرُوا وَتَتَّقُوا وَيَأْتُوكُم مِّن فَوْرِهِمْ هَٰذَا يُمْدِدْكُمْ رَبُّكُم بِخَمْسَةِ آلَافٍ مِّنَ الْمَلَائِكَةِ مُسَوِّمِينَ\"\nبدأ القتال بين المسلمين والمشركين يوم السبت السابع من شهر شوال في السنة الثالثة من الهجرة، \nومحصلش مبارزة زي ما حصل في غزوة بدر، على طول بدأ القتال\nوأسرع طريق لكسب المعركة وهزيمة العدو عند العرب هو إسقاط راية الخصم، فهجم المسلمون على راية المشركين عايزين يسقطوها، \nكان حامل راية المسلمين هو مصعب بن عمير، وكان إللي بيدافع عن راية المشركين بني عبد الدار زي ما قلنا، فبدأوا يدافعوا عنها بكل قوتهم\nكان إللي بيقود المعركة حمزة بن عبد المطلب، وعلي بن أبي طالب والزبير بن العوام كانوا بينظموا القتال بشكل رئيسي،\nحمزة عارف إنه لو أسقط الراية خلاص المعركة انتهت،\nفهجم هو ومجموعة معاه على راية المشركين،\nقعد يقاتل يمين ويسار لحد ما وصل لحامل الراية وقتله\nوسقطت الراية، فطبعا اهتز جيش المشركين في أول كم دقيقة تسقط رايتهم\nعلى طول واحد تاني من بني عبد الدار راح ماسك الراية ورافعها، فراح حمزة ضربه وقتله فسقطت الراية للمرة الثانية\nفقام أخوهم الثالث ومسك الراية، واشتد المشركون على حمزة عشان يمنعوه من قتل حامل الراية، وهم بيدفعوا حمزة عن الراية علي بن أبي طالب ومعاه مجموعة من المسلمين هجموا من الناحية التانية على حامل الراية فقتلوه وسقطت الراية\nفقام أخوهم الرابع وحمل الراية، وعلي بن أبي طالب لسه موجود حول الراية فاستطاع إنه يهجم على حامل الراية وقتله وسقطت الراية للمرة الرابعة\nوالمشركين معنوياتهم باظت، تخيلوا كده الموقف ، المشركين شايفين من بعيد الراية بتاعتهم كل شوية تقع وترتفع ..تقع وترتفع\nفالمشركين اجتمعوا حول علي رضي الله عنه بيدفعوه بعيد عن الراية، وقام أخوهم الخامس ورفع الراية،\nفي نفس الوقت إللي المشركين بيدفعوا حمزة وعلي، جاء عاصم بن ثابت رضي الله عنه ومعاه مجموعة وهجم على حامل الراية وقتله وسقطت الراية\nوعاصم بن ثابت من السابقين للإسلام من الأنصار، وبعد إسلامه عاهد الله إنه لا يمس مشرك ولا يمسه مشرك،\nوكان من المقاتلين الأقوياء،\nفالمشركين مبقوش عارفين يعملوا إيه، يقاتلوا من هنا المسلمين يهجموا من الناحية التانية،\nمع إن عدد المشركين أكبر، لكن ربنا مع المسلمين، ومن كان الله معه يبقى مفيش حد يقدر يقف قصاده\nفمسك الراية أخوهم السادس فقتله عاصم برده، \nامرأة اسمها سُلافَة لما شافت الراية كل شوية تقع وتترفع عرفت إن حامل الراية بيُقتل فتوجهت ناحية الراية فوصلت مع قتل عاصم لاثنين من حملة الراية وكان الاثنان هم أولادها\nفصرخت وقالت:\nمن يأتيني برأس عاصم أشرب في جمجمته الخمر وأعطي وزنها ذهبا لمن يأتيني به\nفاجتمع الناس على عاصم عايزين يقتلوه لكن هو كان قوي محدش قدر يقتله،\nوحمل الراية واحد تاني من بني عبد الدار للمرة السابعة، اجتمع بعض المشركين مع بعض وقالوا لو الوضع استمر كده هتبقى كارثة، لازم نشوف حل\nفقالوا إيه الحل\nقالوا زي ما هم بيهاجموا الراية بتاعتنا احنا كمان نهاجم رايتهم\nفجهزوا مجموعة وانطلقوا نحو مصعب بن عمير عايزين يقتلوه عشان يسقطوا راية المسلمين، ومصعب ثابت بيدافع عن راية الإسلام والمسلمين معاه بيحموه،\nوبقى في معركتين في نفس الوقت، معركة عند راية المشركين ومعركة عند راية المسلمين،\nفي الوقت ده كان في كتيبة من المشركين بقيادة خالد بن الوليد بتحاول تلف خلف جيش المسلمين من ناحية الجبل إللي عليه الرّماة إللي اتكلمنا عنهم المرة إللي فاتت، عشان يهجموا على المسلمين من الخلف،\nفأول ما قرب خالد بن الوليد لقى سيل من السهام نازل عليهم من فوق الجبل فتراجع ومقدرش يهجم، وكل شوية يحاول يقرب تمنعه سهام الرماة وفشلت محاولاته\nاستطاع حمزة وعلي وعاصم إنهم يصلوا لحامل راية المشركين فقتلوه وسقطت الراية للمرة السابعة،\nوالمشركين بيتصدموا كل صدمة والتانية ومش عارفين يعملوا إيه ولواء المسلمين ثابت متحركش\nحمل راية المشركين واحد ثامن من بني عبد الدار برده، ما همّ وعدوا أبو سفيان إنهم هيقاتلوا وهيدافعوا عن الراية، وكان من طبيعة العرب إنهم بيوفُّوا بكلمتهم ولو على رقبتهم\nوالمشركين بيحاولوا يدافعوا ويحموا حامل الراية والمسلمين عايزين يوصلوا له ويقتلوه،\nفي نفس وقت معركة الرايات كانت في أحداث تانية بتحصل في أرض المعركة زي مثلا رسول الله ﷺ كان يَنبِل لسعد بن أبي وقاص، يعني كان رسول الله ﷺ بيعطيه السهام ويقول له :\nارمِ فداك أبي وأمي!\nيعني رسول الله ﷺ بيقول له يرمي السهام على المشركين، وفداك أبي وأمي كلمة للتعبير عن حبه لسعد وعظم منزلته عنده،\nمش إنه يعني هيفدي سعد بأبوه وأمه، لأن في الوقت ده كان أبواه ﷺ ميتين، ولم يجمع رسول الله ﷺ أبويه لأي أحد غير سعد بن أبي وقاص رضي الله عنه\nفكان سعد لما يضرب بالسهم يصيب به المشركين إما يقتلهم أو يصيبهم بجرح،\nخرج واحد من بني عبد الدار ضخم ومغطي نفسه بالدروع وكان راكب على جمل وهو من أقوى فرسان قريش،\nوكانوا بيسموه كبش الكتيبة،\nالمسلمين لما شافوا منظره خافوا، فقام الزبير بن العوام وراح ناحيته عشان يحاول يقتله،\nمش عارف يقتله إزاي راح ناطط فوق الجمل وشد الرجل وقعه في الأرض وقعد عليه وقتله\nفلما شافه رسول الله ﷺ قال:\nإن لكل نبي حواري وحواريي الزبير، الحواري يعني الناصر  من أصحابه ﷺ،\nالمسلمون قتلوا إحدى عشر رجل من حاملي الراية، ولحد دلوقتي المشركين لم يقتلوا ولا واحد من المسلمين،\nفكانت معنوياتهم صفر،\nوكان من أشد المقاتلين أبو دجانة الأنصاري إللي أخذ سيف رسول الله ﷺ ،انطلق يقاتل المشركين وراح وراءه الزبير بن العوام بيراقبه ويشوفه هيعمل إيه بالسيف،\nفكان أبو دجانة يقتل بسيف رسول الله ﷺ أي واحد يقابله من المشركين، \nواخترق أبو دجانة صفوف المشركين لحد ما وصل لآخر الجيش بتاعهم وكان في آخر الجيش النساء ودي كانت من عادة العرب،\nإنهم يخلوا النساء في آخر الجيش عشان لو حصل هزيمة تكون النساء أول الهاربين فميقعوش رهينة في أيدي أعدائهم،\nفرأى أبو دجانة إنسان عمال يشتم في الناس فرفع السيف ولسه هيقتله لقاه بيوَلْوِل، فعرف إنها امرأة ومرضاش يقتلها،\nقال أكرمت سيف رسول الله أن أضرب به امرأة،\nيعني هو شاف إن مش من الرجولة إنه يقتل امرأة بسيف رسول الله ﷺ، \nوكانت المرأة دي هي هند بنت عتبة زوجة أبو سفيان، فتركها وذهب\n☆ هو ليه المشركين أخذوا معاهم نساء للمعركة \nالرجل العربي طبيعته الأصيلة إنه بيغير على نسائه جدا وفي قصص كتير عن غيرة العرب قبل الإسلام وحتى غيرة الصحابة، \nفكان وجود النساء في الجيش دافع كبير جدا إنهم لا ينهزموا أمام أي عدو، لأنهم لو انهزموا نسائهم هيكونوا إماء، عبيد يعني فبيحاربوا بكل قوتهم عشان نسائهم لا يقعوا في الأسر\n☆معنى كده إن المسلمين كانوا بياخدوا نسائهم معاهم الحروب \nالجهاد غير واجب على النساء، والسيدة عائشة سألت رسول الله ﷺ هل على النساء جهاد، فقال لها :\nجهاد لا قتال فيه، الحج والعمرة. وعشان هي مش من أهل القتال لضعفها،\nوقال العلماء إن قتالها ممكن يكون سبب في كشف عورتها، وممكن يكون سبب لجرأة المشركين على المسلمين، \nده غير إن ممكن حد من المشركين يأخذ النساء أسرى ويستبيح أعراضهن،\nعشان كده مكنش في جيوش من النساء زي الرجال، \nلكن كان في بعض النساء بيخرجن مع الجيش، زي ما رسول الله ﷺ كان بيأخذ بعض زوجاته معاه، وزي بعض النساء 《العجائز》 إللي كانوا بيخرجن مع المسلمين عشان يسقين الجيش الماء،\nويُداوين الجرحى لأن الرجال بينشغلوا بالحرب ومفيش حد يقوم بالمهمة دي، فاللي بيخرج لسُقيا الماء ومداواة الجرحى هم النساء العجائز، \nأما النساء الصغيرات في السن لا يخرجن لخوف الفتنة\n《شرح الموضوع بالتفصيل في موقع الإسلام سؤال وجواب》\nالكلام ده كله \nفي جهاد الطلب، يعني إن المسلمين يخرجوا يقاتلوا برة البلد، أما لو هجم العدو على بلد من بلاد المسلمين فالجهاد في الحالة دي فرض عين على كل واحد من المسلمين حتى النساء بحسب استطاعتها وقدرتها، وده اسمه جهاد الدفع،\nيعني ندفع العدو عن بلدنا، وحتى المرأة ساعتها تخرج بدون إذن زوجها عادي.\nوسط القتال ومع اشتداد المعركة سقط أول شهيد من شهداء المسلمين، عبد الله بن حرام، إللي اتكلمنا عنه المرة إللي فاتت، وقُتل عمرو بن الجموح صاحبه إللي كان عنده عرج في رجله،\nوكان سأل رسول الله ﷺ هل لو أنا مت شهيد هدخل الجنة ورجلي تبقى صحيحة مفيهاش عرج\nفقال له رسول الله ﷺ: نعم\nفحلف وقال والله ما أرجع إلى بيتي حتى أدخل الجنة\nفعمر بن الخطاب رضي الله عنه قال له:\nمتحلفش على ربنا\nفقال له رسول الله ﷺ:\nاستنى يا عمر! في ناس لو أقسموا على الله لأبرّهم منهم عمرو بن الجموح\nفقاتل عمرو حتى قُتل رضي الله عنه،\nحمزة بقى رضي الله عنه من بداية المعركة واحنا شايفين شدته على المشركين، ومكنش حد يقرب منه إلا ويقتله فخرج رجل من المشركين يتحدى المسلمين في مبارزة ،\nفتقدم له حمزة وقتله بضربة واحدة\nمين إللي كان بيراقب حمزة وهو بيقتل ده ويقتل ده \nوحشي بن حرب إللي سيده جبير بن مطعم وكان وعده لو قتل حمزة هيعطيه حريته،\nفسأل وحشي الناس إللي حواليه هو مين ده إللي عمال يهزم أي حد يقرب منه\nفقالوا له ده حمزة بن عبد المطلب\nفقال وحشي، أيوة هو ده إللي بدور عليه\nووحشي مكنش عارف حمزة لأنه كان مغطي نفسه بالدرع بتاعه، \nفضل وحشي يراقب حمزة من بعيد ومعاه حربة في إيده وكان ماهر جدا في الرماية ونادرا لو أخطأ هدفه،\nفاضل مستخبي وماسك الحربة في إيده بيهزها مستني الفرصة المناسبة عشان يرمي بها حمزة،\nوحمزة بيتحرك هنا وهنا بطنه انكشفت راح وحشي رامي الحربة دخلت في بطنه تحت سرته،\nوسقط حمزة وحاول إنه يقوم مقدرش ومات شهيدا رضي الله عنه\nعلى الرغم من سقوط حمزة إلا إن المسلمين استمروا في قتالهم ضد المشركين بكل قوة، وحصل الاضطراب في جيش المشركين وخصوصا إن بعد مقتل حامل الراية الحادي عشر محدش حملها مرة ثانية،\nفانهزم المشركون وبدأوا يهربوا، انتصار زي انتصار بدر،\nالمسلمين سبعمائة والمشركين ثلاثة آلاف لكن :\n\" إِنْ يَنْصُرْكُمُ اللَّهُ فَلا غَالِبَ لَكُم\" \nهرب المشركون وتركوا وراءهم النساء والأموال والدروع،\nكل واحد هرب بحياته، فكان نصر عظيم للمسلمين \n\"وَلَقَدْ صَدَقَكُمُ اللَّهُ وَعْدَهُ إِذْ تَحُسُّونَهُم بِإِذْنِهِ\"\nبدأ المسلمون في أرض المعركة يلموا الغنائم، خلاص تقريبا المعركة انتهت ومبقاش في حد في أرض المعركة ما عدا كتيبة واحدة بس هي كتيبة خالد بن الوليد إللي كانت بتراقب المعركة من بعيد،\nفي ناس تانية شافت المسلمين وهم بيلموا الغنائم، فهياخدوا قرار خطير جدا هيغير كل حاجة في أرض المعركة \nمين الناس دي، وإيه الكارثة إللي هتحصل للمسلمين ده إللي هنعرفه الجزء الجاي إن شاء الله\n☆"}, {"n": 100, "l": "الجزء 74 | الهزيمه في احد", "u": "https://www.facebook.com/groups/710210019782034/permalink/812768679526167/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية_\n#الحلقة_الرابعة_والسبعون\n#الهزيمة_في_أحد\nكنا واقفين المرة إللي فاتت عند نصر المسلمين في غزوة أحد، وقلنا إن المشركين هربوا من أرض المعركة وبدأ المسلمون بجمع الغنائم،\nهرب المشركون ما عدا كتيبة خالد بن الوليد إللي كانت بتحاول تلف من حول جبل الرماة عشان تهجم على المسلمين فجأة، وكانوا كل ما يتقدموا يردهم سهام المسلمين من على جبل الرماة،\nانتظر خالد بن الوليد بالكتيبة بتاعته بعيد يراقب المعركة عشان ينتهز أي فرصة تخليه يتقدم ويهجم على المسلمين،\nالرماة على الجبل شافوا إن المعركة خلاص خلصت لدرجة إن المسلمين بيلموا الغنائم،\nفقاموا إلا قليلا منهم عشان ينزلوا من على الجبل يلموا الغنائم عشان يضمنوا نصيبهم،\nماهم قاعدين فوق الجبل من الصبح يدافعوا عن المسلمين،\nفعايزين يأخذوا نصيبهم في جمع الغنائم\nفعبد الله بن جبير قائدهم قال لهم:\nانتم رايحين فين\nفقالوا : خلاص المعركة خلصت والناس بتلم الغنائم ،هنقعد هنا نعمل إيه، هنروح نلم الغنائم احنا كمان\nفقال لهم عبد الله بن جبير:\nبس رسول الله ﷺ كلامه كان واضح، قال منتحركش من مكاننا مهما حصل لحد ما هو يُرسل حد يقول لنا سواء انتصر المسلمون أو انهزموا\nمعظمهم مسمعوش كلام عبد الله بن جبير على أساس إنهم شايفين إن خلاص المعركة انتهت هنستنى إيه تاني،\nوممكن رسول الله ﷺ يكون انشغل أصلا بحاجات تانية فعشان كده لم يرسل إلينا، فخلاص بقى مهمتنا انتهت\nعبد الله بن جبير صمّم على موقفه وقام وخطب فيهم وقال لهم : \nهتعملوا إيه في كلام رسول الله ﷺ، لازم تطيعوا أوامر رسول الله ﷺ، مينفعش تخالفوا أمره\nفقاموا وتركوه ونزلوا من على الجبل، وقعد مع عبد الله بن جبير عدد قليل جدا يُقال إنهم عشرة أو أقل من العشرة،\nكان مراقب الأحداث دي من بعيد خالد بن الوليد وكان قائد عسكري عظيم، لدرجة إنه لم يخسر معركة واحدة في حياته أبدا\nفأول ما خالد شاف الرماة نزلوا من على الجبل انطلق بسرعة ناحية الجبل وكان معاه عكرمة بن أبي جهل،\nوصلوا للجبل، الرماة الباقيين رموهم بالسهام إللي معاهم وأصابوا بعضهم لكن جيش استطاع إنه يوصل للرماة وقتلوهم، عبد الله بن جبير رماهم بالسهام إللي معاه لحد ما خلصت،\nوقاتل بالرمح بتاعه لحد مانكسر، وكسر جفن السيف، يعني الجراب إللي بيتحط فيه السيف وقعد يقاتل به لحد ما قُتل رضي الله عنه، وكان الذي قتله عكرمةُ بن أبي جهل،\nوكأن عبد الله بن جبير بيحاول إنه ينفذ وصية وأمر رسول الله ﷺ إنه لا يُؤْتَى المسلمون من قِبَلِك،\nيعني إوعى إنت تكون الباب إللي يدخل منه المشركون ويهزموا المسلمين\nمات عبد الله بن جبير في سبيل الدفاع عن أمر رسول الله ﷺ للنهاية،\nومع إنه كان لوحده مع عدد قليل إلا إنه صمم على موقفه، مقلش : \nيعني أنا لوحدي إللي صح وهم كلهم غلط، مش يمكن معاهم حق\nهو ثبت على على موقفه لحد آخر لحظة في حياته، فنتعلم من عبد الله بن جبير إن أصحاب الحق ناس قليلة،\nوإن مهما الناس مشيوا في طريق الخطأ فاحنا لازم نثبت على موقفنا مهما كنا قليلين ولوحدنا مادام معانا نص كلام رسول الله ﷺ \n☆ احنا شايفين إن الرماة أخطأوا وكانوا سبب في قتل صاحبهم عبد الله بن جبير ومتضايقين من إللي عملوه ،صح؟\nتخيلوا إن احنا بنعمل نفس الخطأ إللي الرماة عملوه وزعلانين منهم واحنا مش واخدين بالنا\nالرماة اجتهدوا وأفتوا نفسهم بفتوى غلط ومشيوا وراء الدنيا، مع إن في نص واااضح من رسول الله ﷺ :\nمحدش يسيب مكانه مهما حصل \nبسبب اتباعهم لرغباتهم الدنيوية وهي إنهم يجمعوا الغنائم قُتل أصحابهم،\nودلوقتي في واقعنا ناس كتيييير جدا بتفتي نفسها مع إن قصادها النص الواضح من رسول الله ﷺ،\nوتتبع هواها ورغباتها في الدنيا سواء مال حرام من ربا، أو تتنمص عشان شكلها يبقى حلو،\nأو تسمع الأغاني بحجة إنها غذاء الروح، أو تلبس المجسم والمقطع والقصير والحجاب إللي مش حجاب عشان شكلها يبقى حلو وخايفة من كلام الناس،\nمع إن كل الحاجات دي وغيرها كتييير فيها نص من رسول الله ﷺ\nتعتقدوا إن الرماة لو كانوا يعرفوا إن بسبب اجتهادهم الخاطئ ده وتركهم أمر رسول الله ﷺ أصحابهم هيموتوا كان هيسيبوا مكانهم؟\nطبعا لأ\nطيب هم مكنوش يعرفوا إن عاقبة عصيانهم لأمر رسول الله ﷺ الواضح الصريح هتكون كارثية،\nلكن احنا عرفنا وشفنا، فهل هنتعظ ونعتبر ونتعلم من خطأهم ولا هنستمر في عصيان أوامر رسول الله ﷺ الصريحة الواضحة وتحصل لنا الكوارث المستمرة إللي احنا بنستغرب منها وبنقول ليه يارب كده؟\nواحنا أصلا السبب فيها :\n\"وَمَا أَصَابَكُم مِّن مُّصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُو عَن كَثِيرٍ\"\n\"أَوَلَمَّا أَصَابَتْكُمْ مُصِيبَةٌ قَدْ أَصَبْتُمْ مِثْلَيْهَا قُلْتُمْ أَنَّى هَذَا قُلْ هُوَ مِنْ عِنْدِ أَنْفُسِكُمْ \"\nبعد ما سقط عبد الله بن جبير ميتا، مثّل المشركون بجثته، يعني قعدوا يقطعوا في جسمه، ويضربوه بالرماح والسيوف،\nلدرجة إن أحشاء بطنه خرجت\nوياريت المأساة وقفت لحد هنا\nبعد ما كتيبة خالد بن الوليد قضت على باقي الرماة صاح بالمشركين، نادى عليهم بصوت عالي فسمع صوته المشركون وعرفوا إن خالد الْتف من وراء جيش المسلمين فبدأوا يجمعوا نفسهم ويرجعوا للقتال،\nوحصر المشركون المسلمين من الجهتين، من الأمام ومن الخلف، وبسرعة راحت امرأة من المشركين ورفعت راية المشركين إللي كانت واقعة على الأرض،\nالمشركين اتحمسوا وبدأوا يجمعوا صفوفهم من تاني بسرعة وهجموا على المسلمين إللي تفاجؤوا برجوع المشركين لأرض المعركة،\nوبدأوا يسمعوا صوت صراخ من ورائهم فرجعوا للخلف مش عارفين في إيه، فشافوا جيش جاي عليهم من ورائهم،\nومع اللخبطة إللي حصلت، المسلمين بدأوا يقاتلوا بعض\nماهم معظمهم لابسين دروع مغطية جسمهم وحاطين على رأسهم خوذة الحرب فمش ظاهر منهم حاجة،\nلدرجة إن واحد من الصحابة اسمه حُذَيفة بن اليمان شاف المسلمين بيقتلوا أباه اليَمان وكان من المسلمين وقعد بيصرخ فيهم :\n يا جماعة ده أبي..أبي، وهم مش عارفينه ولا سامعين حذيفة، فلما عرف المسلمون حزنوا جدا لمقتل أبو حذيفة رضي الله عنهما،\nفقال لهم حذيفة: يغفر الله لكم وهو أرحم الرحمين، وانطلق بعدها يقاتل في سبيل الله ،\nمع إن الموقف صعب وشاف أبوه بيقتل أمامه إلا إنه كان عنده هدف أسمى، مش ده وقت الحزن والبكاء،\nالحياة مش هتقف، خلاص أبوه مات شهيدا وأدى دوره وانتهى الموضوع، الدور والباقي علي أنا \nوبعد المعركة هيرفض إنه يأخذ الدية عن مقتل والده وهيتصدق بها على فقراء المسلمين،\nجيش المسلمين بقى فوضى وبقوا مش عارفين يقاتلوا إللي جاي من أمامهم ولّا إللي من خلفهم، رسول الله ﷺ في الوقت ده كان في آخر الصفوف بينظم الجيش فلما التف خالد خلف الجيش  كان أول فرقة يواجهها هي الفرقة إللي فيها رسول الله ﷺ\nرسول الله ﷺ قائد الجيش شاف الاضطراب إللي حصل في جيش المسلمين وشاف خالد وهو متقدم ناحيته،\nفكان قصاده حل من اثنين :\nإما إنه ينسحب بالمجموعة إللي معاه لحد ما يقدر ينظم صفوف المسلمين مرة ثانية وده ممكن يأخذ وقت،\nوبكده يعرض المسلمين للهلاك،\nأو إنه ينادي على المسلمين بحيث إنه ينبههم ويجتمعوا عنده\n وينظم صفوفهم لأنهم دلوقتي في حالة ذهول زي ما بنقول محتاجين إللي يفوقهم،\nولكنه كده ممكن يعرض حياته للخطر،\nلأن المشركين لو سمعوا صوته هيتوجهوا ناحيته ويحاولوا يقتلوه، وخصوصا إن مكنش معاه غير تسعة فقط من أصحابه سبعة من الأنصار واثنين من المهاجرين،\nفاختار رسول الله ﷺ إنه ينادي على المسلمين عشان يجمع صفوفهم من تاني فقال:\n\"إليّ عباد الله! إليّ عباد الله! أنا رسول الله\"\nيعني أنا رسول الله تعالوا عندي يا عباد الله، \nوبدأ يعلي صوته عشان المسلمين يسمعوه وهم في حالة اضطراب شديد والمشركين هاجمين عليهم،\nسمع صوت رسول الله ﷺ  خالد بن الوليد فتوجه ناحية مصدر الصوت ومعاه جيشه وهجم على رسول الله ﷺ والمجموعة إللي معاه وبدأ عتبة بن أبي وقاص يرمي الحجارة على رسول الله ﷺ فأصابته الحجارة فانفجر الدم من وجهه ﷺ \nفتراجع رسول الله ﷺ فسقط في حفرة من الحفر إللي حفرها أبو عامر الراهب إللي سماه رسول الله ﷺ الفاسق،\nوكان من المشركين الذين هجموا على رسول الله ﷺ واحد اسمه عبد الله بن قَمِئَة، \nضرب رسول الله ﷺ بالسيف على كتفه ضربة شديدة جدا، لكنه لم يُصَب بجرح لأنه كان لابس درعين، لكن ألم الضربة استمر وجعه شهر كامل، \nوضربه ابن قمئة مرة ثانية على وجهه وكان لابس خوذة الحرب فدخلت حلقتين من حلقات الخوذة إللي هي المِغْفْر في خدّيْ رسول الله ﷺ وكُسِرت ربَاعِيّته، \nوهي السّنة إللي بين الناب والأسنان الأمامية دي عارفينها\n حاصر خالد بن الوليد رسول الله ﷺ والمجموعة إللي كانت معاه، والتف الصحابة حول رسول الله ﷺ بيحاولوا يحموه من الهجمات إللي نازلة عليه وراء بعضها، \nهم كانوا بيحبوا رسول الله ﷺ حب عظيم جدا أكثر من حبهم حتى لأنفسهم،\nفتخيلوا منظر التسعة وهم محاوطين رسول الله ﷺ  بسيوفهم عشان يدافعوا عنه، تسعة مقابل فرقة كاملة من الفرسان، قال لهم رسول الله ﷺ عشان يشجعهم:\nمن يردهم عنا وله الجنة وفي رواية وهو رفيقي في الجنة،\nفانطلق واحد من الأنصار وقاتل الفرسان بكل قوة حتى قُتل، \nوتقدم الثاني وقاتل حتى قُتل،\n والثالث والرابع لحد السابع قاتلوا جميعا للدفاع عن رسول الله ﷺ  لحد ما استشهدوا جميعا،\nولم يتبقّ مع رسول الله ﷺ إلا الاثنين من المهاجرين، طلحة بن عبيد الله وسعد بن أبي وقاص، \nوبدأ طلحة بن عبيد الله يقاتل دفاعا عن رسول الله ﷺ بسيفه، لحد ما أصيب تسعة وثلاثين جرح ،وسعد يرمي المشركين بالسهام، \nوهم عايزين يقربوا ويقتلوا رسول الله ﷺ بأي طريقة، \nفواحد رمى رسول الله ﷺ من بعيد بسهم فوضع طلحة يده أمام السهم فدخل السهم في يده وأنقذ طلحة رسول الله ﷺ من السهم، لكن يده شُلّت بعدها رضي الله عنه،\nفي وسط دفاع سعد وطلحة عن رسول الله ﷺ جاء مجموعة من الصحابة وعلى رأسهم أبو بكر الصديق، فشاف رسول الله ﷺ ساقط في الأرض وشاف واحد عمال يقاتل ويدافع عنه بكل قوة،\nفقال أبو بكر الصديق رضي الله عنه:\nكن طلحة، كن طلحة فداك أبي وأمي\nلأنه عارف إن طلحة مقاتل شديد قوي، فتمنى إن يكون المقاتل الشديد ده هو إللي يدافع عن رسول الله ﷺ، \nفلما وصل أبو بكر لرسول الله ﷺ لقى إللي بيدافع ويقاتل ده هو طلحة فعلا،\n وجاء وراءه عمر بن الخطاب وأبو عبيدة بن الجراح وبدأ يتجمع المسلمون ويتجهوا نحو رسول الله ﷺ، \nمن الناس إللي توجهت ناحية رسول الله ﷺ مصعب بن عمير إللي كان معاه راية المسلمين،\nلحد دلوقتي كان محافظ عليها من السقوط، وكان مصعب يشبه رسول الله ﷺ جدا فقابله عبد الله بن قمئة مع مجموعة من المشركين فقاتلهم مصعب،\nفقطعوا يده إللي ماسكة الراية، فبسرعة مصعب راح ماسكها بإيده التانية عشان متقعش، فقطعوا يده الثانية فقعد على الأرض وحاول يمسك الراية بعضديه، يعني بكتفه وجسمه كله عشان متسقطش،\nفضربه بالسيف عبد الله بن قمئة وقال:\n قتلنا محمدا! قتلنا محمدا!\nعلى أساس الشبه إللي كان بين مصعب وبين رسول الله ﷺ،\nفسقط مصعب بن عمير رضي الله عنه على الأرض وهو يقول :\n\"وَمَا مُحَمَّدٌ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ الرُّسُلُ ۚ أَفَإِن مَّاتَ أَوْ قُتِلَ انقَلَبْتُمْ عَلَىٰ أَعْقَابِكُمْ ۚ وَمَن يَنقَلِبْ عَلَىٰ عَقِبَيْهِ فَلَن يَضُرَّ اللَّهَ شَيْئًا ۗ وَسَيَجْزِي اللَّهُ الشَّاكِرِينَ\"\nأجراها الله على لسانه قبل ما تُنزّل على رسوله ﷺ، ومات مصعب بن عمير، مات مَن كان أنعم شباب مكة، \nمات مَن كانت الدنيا في يده وتركها عشان الإسلام ، مصعب إللي كان بيلبس أفخم الثياب رآه رسول الله ﷺ وهو عليه جلد كبش خشن، جلد خروف يعني، لا يستر كل جسمه فقال للصحابة:\nشوفوا للرجل إللي ربنا نوّر قلبه ده، أنا شفته كان عايش بين أبوين بيأكّلوه أحسن الطعام، فدعاه حب الله ورسوله إلى ما ترون\nيعني حب الله ورسوله دفع مصعب بن عمير للحالة إللي انتم شايفينها دي، وأهه مات ومعندوش من الدنيا إلا نَمرة يعني كساء غليظ،\nثوب فيه خطوط بيضاء وسوداء، لما المسلمين حاولوا يكفنوه فيها مكنتش مكفياه لما يغطوا رأسه كانت رجله تظهر، ولما يغطوا رأسه كانت رأسه تظهر،\nلو فكرنا في حال مصعب من الناحية الدنيوية هنلاقيه إنه مسكين، \nمستمتعش بالدنيا خالص، حياته كلها تعب، تعذيب من أمه وهجرة للحبشة وبعدها هجرة للمدينة وبذل مجهود خرافي في الدعوة وفي الآخر مات فقير معندوش أي حاجة من متاع الدنيا، ومات هو شايف هزيمة المسلمين بعينه،\nلكن ولأَجر الآخرة خير، كل شقاء مصعب في الدنيا، انتهى بمجرد خروج روحه\nونزلت في مصعب بن عمير وأمثاله:\n\"مِّنَ الْمُؤْمِنِينَ رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ ۖ فَمِنْهُم مَّن قَضَىٰ نَحْبَهُ وَمِنْهُم مَّن يَنتَظِرُ ۖ وَمَا بَدَّلُوا تَبْدِيلًا\"\nاحنا بقى عملنا إيه، تنازلنا عن إيه عشان حب الله ورسوله، ضحينا بإيه غالي علينا عشان نبقى ماشيين على نفس طريق مصعب، محتاجين وقفة مع نفسنا مش كده\nالخبر انتشر بسرعة في أرض المعركة إن رسول الله ﷺ قُتل، ووصل الخبر للمسلمين إللي كانوا بعيدين عن رسول الله ﷺ والمجموعة إللي كانت معاه، \nفي ناس من المسلمين هربوا من أرض المعركة وتوجهوا للمدينة، وبعدين ربنا عفا عنهم زي عثمان بن عفان رضي الله عنه، وفيهم نزل قول الله :\n\"إِنَّ الَّذِينَ تَوَلَّوْا مِنكُمْ يَوْمَ الْتَقَى الْجَمْعَانِ إِنَّمَا اسْتَزَلَّهُمُ الشَّيْطَانُ بِبَعْضِ مَا كَسَبُوا ۖ وَلَقَدْ عَفَا اللَّهُ عَنْهُمْ ۗ إِنَّ اللَّهَ غَفُورٌ حَلِيمٌ \"\nوفي ناس تانية اتصدمت ومبقتش عارفة تعمل إيه، مش قادرين يتخيلوا إزاي رسول الله ﷺ يُقتل، طيب والوحي ..والرسالة...فجالهم احباط لدرجة إن بعض المسلمين قعدوا في الأرض وتركوا حتى الدفاع عن نفسهم\nفعدى عليهم صحابي اسمه ثابت بن الدحداح، فسألهم انتم ليه قاعدين كده\nفقالوا له مات رسول الله ﷺ \nفقال لهم : إن كان رسول الله ﷺ خلاص قُتل فإن الله حي لا يموت، وانطلق يقاتل المشركين لحد ما قُتل شهيدا رضي الله عنه، \nوكأنه بيرسل لنا رسالة بيقول لنا:\nإنتم مش بتعملوا عشان بشر، إنتم بتعملوا أعمالكم عشان رب البشر إللي شايف تعبكم وجهادكم في سبيله\nحتى أنس بن النّضر مرّ على مجموعة من المسلمين قاعدين مش بيتحركوا فقال لهم إنتم مستنيين إيه\nفقالوا : قُتل رسول الله ﷺ \nفقال لهم:\nقوموا فموتوا على ما مات عليه رسول الله\nرسالة تانية لنا من أنس :\nمتوقفش حياتك على حد، كمّل رسالتك لحد آخر نفس\nأنس بن النّضر إللي قال لما فاتته غزوة بدر :\n لئن كان لرسول الله ﷺ قتال ثاني مع قريش ليرين الله  ما أصنع،\nجاء وقت اختباره، هل فعلا هيكون على قدر كلمته إللي قالها ولّا كانت مجرد كلمات حماسية وقتية،\nنظر أنس بن النضر للمسلمين المستسلمين وللمشركين وقال:\nاللهم إني أعتذر إليك مما فعل هؤلاء وأبرأ إليك مما فعل هؤلاء، وتقدم رضي الله عنه ليقاتل المشركين ويُري الله تعالى إنه كان صادق في كلامه،\nفقابله سعد بن معاذ وهو منطلق ناحية المشركين فسأله :\nإنت رايح فين يا أبا عمر\nفقال له أنس : ياااه على رائحة الجنة يا سعد، أنا شامم ريحتها من عند أُحد \nودخل أنس وسط المشركين وقعد يقاتلهم قتالا شديدا ومهما انضرب بالسيف وجُرح لم يتراجع وفضل يقاتل حتى قتل شهيدا رضي الله عنه، وأثبت فعلا صدق كلامه،\nماهو إللي قال فيه رسول الله ﷺ قبل كده إن من الناس من لو أقسم على الله لأبرّه لما أخته الرُّبَيّع كسرت سن من أسنان جارية فطلبوا العفو من أهل الجارية فرفضوا،\n فطلبوا إنهم يدفعوا لهم دية السن إللي اتكسر، يعني مال مقابل السن دي، فرفض أهل الجارية والرُّبَيّع دي هي\nأم حارثة إللي قُتل ابنها قبل بداية غزوة بدر واتكلمنا عنه وقتها، ولما سألت عليه رسول الله ﷺ قال لها:\nويْحَكِ يا أم حارثة أهبلتي إنها ليست جنة واحدة إنها جنان وإن حارثة قد أصاب الفردوس الأعلى،\nفذهب أهل الجارية إلى رسول الله ﷺ وأخبروه باللي حصل فأمرهم بالقصاص، فقال أنس بن النضر:\nأتُكْسَرُ ثَنيّة الرّبيّع يارسول الله\nلا والذي بعثك بالخق لا تُكسر ثَنِيّتُها \nفقال له رسول الله ﷺ: يا أنس كتاب الله القصاص!\nفرَضيَ أَهل الجارية وعفوا، فقال رسول الله ﷺ:\nإن من عباد الله من لو أقسم على الله لأبره،\nيعني لو حلف على شيء إنه يحصل ثقة بالله وبحسن ظنه به ربنا هيحقق له قسمه ده\nوبعد ما قُتل أنس مثّل المشركون بجثته، ومحدش قدر يتعرف عليه غير أخته الرّبَيّع بنت النضّر عن طريق بنانه، إصبعه يعني ولقوا في جسمه بضع وثمانين جرح، ما بين ضرب بالسيف وطعن بالرمح ورمي بالسهام،\nصدق أنس الله فصدقه الله:\n\"مِّنَ الْمُؤْمِنِينَ رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ ۖ فَمِنْهُم مَّن قَضَىٰ نَحْبَهُ وَمِنْهُم مَّن يَنتَظِرُ ۖ وَمَا بَدَّلُوا تَبْدِيلًا\"\nفي الوقت ده كان رسول الله ﷺ واقع لسه في الحفرة مش عارف يقوم بسبب الدم إللي نزل منه والجراح إللي كانت فيه، فلما وصل عنده أبو بكر وباقي الصحابة قال لهم:\n ساعدوا طلحة فهو عمل كل إللي عليه، \nولما وصل الصحابة وبدأوا يدافعوا عن رسول الله ﷺ سقط طلحة على الأرض من كثرة الجراح والتعب،\nشاف أبو عبيدة بن الجراح حلقتي المِغْفر داخلين في وجه رسول الله ﷺ فحاول يشيلها معرفش،\nفاستعمل أسنانه عشان ينزعها من وجه النبي ﷺ،\nفسقطت ثنيّتان من أسنانه رضي الله عنه،\nالصحابة شافوا إن وجود رسول الله ﷺ في المكان ده خطر عليه فلازم يتحركوا منه،\nلكن لازم الأول يردوا المشركين عنه فبدأوا يدافعوا عنه بكل قوتهم،\nوجاء بعض المسلمين لمكان رسول الله ﷺ ومنهم كعب بن مالك وعرف إن رسول الله ﷺ لم يُقتل فنادى في المسلمين : أبشروا أبشروا، رسول الله حي!\nفأشار له رسول الله ﷺ إنه يسكت عشان ميسمعوش باقي المشركين فيجتمعوا عليه، \nفسمع كلام كعب ثلاثين رجلا من المسلمين فجاؤوا بسرعة لرسول الله ﷺ وبدأت خطة الانسحاب من أرض المعركة.\nيا ترى إيه إللي حصل بعد كده، \nده إللي هنعرفه الجزء الجاي إن شاء الله \n♡"}, {"n": 101, "l": "الجزء 75 | حماية المسلمين لرسول الله في احد", "u": "https://www.facebook.com/groups/710210019782034/permalink/812770252859343/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الخامسة_والسبعون\n#حماية_المسلمين_لرسول_الله_في_أحد\nاتكلمنا المرة إللي فاتت عن هزيمة المسلمين وتعرّض رسول الله ﷺ للأذى الشديد وحتى قيل إنه مات وكان السبب في الهزيمة هو عصيان الرماة لأمر رسول الله ﷺ،\nأكيد في ناس بتسأل :\nهو ليه رسول الله ﷺ والمسلمين إللي معاه يتحملوا نتيجة خطأ مجموعة منهم، يعني هل من العدل إن السبعمائة إلا قليل يتحملوا نتيجة خطأ أربعين شخص\nيعني كان ربنا ينصر رسول الله ﷺ والمسلمين وبعدين يبقى يعاقب الرماة على عصيانهم \nيجاوبنا على السؤال ده حديث رسول الله ﷺ :\n\"مثل المؤمنين في توَادّهم وتراحُمهم وتعاطفهم مثل الجسد إذا اشتكى منه عُضو تداعى له سائر الجسد بالسهر والحمى\"\nالمسلمين كلهم زي الجسم، هو لو الإنسان ضرسه وجعه ولا إيده وجعته بيقدر ينام؟\nطبعا مبيقدرش، هل العين تقول طب أنا ذنبي إيه إني لا أنام عشان في ألم في الضرس ولّا في اليد، ولّا بتسهر وبتتألم هي كمان؟\nفي الإسلام مفيش حاجة اسمها أهم حاجة نفسي وبس، في الإسلام الفرد ممكن يضحي بمصلحته الشخصية عشان مصلحة الجميع،\nفلما واحد من المسلمين يعمل خطأ يتحمل نتيجته كووول المسلمين\nوهنا ييجي ضرورة الأمر بالمعروف والنهي عن المنكر\nتعالوا كده نشوف حديث السفينة، \nرسول الله ﷺ يقول :\n\"مَثَلُ القَائِمِ في حُدودِ اللَّه، والْوَاقِعِ فِيهَا كَمَثَلِ قَومٍ اسْتَهَمُوا عَلَى سفينةٍ، \nفصارَ بعضُهم أعلاهَا، وبعضُهم أسفلَها، وكانَ الذينَ في أَسْفَلِهَا إِذَا اسْتَقَوْا مِنَ الماءِ مَرُّوا عَلَى مَنْ فَوْقَهُمْ،\nفَقَالُوا: \nلَوْ أَنَّا خَرَقْنَا في نَصيبِنا خَرْقًا وَلَمْ نُؤْذِ مَنْ فَوْقَنَا. \nفَإِنْ تَرَكُوهُمْ وَمَا أَرادُوا هَلكُوا جَمِيعًا، وإِنْ أَخَذُوا عَلَى أَيْدِيهِم نَجَوْا ونَجَوْا جَمِيعًا \"\nيعني مَثل الشخص إللي بيراعي حدود ربنا وبينفذ أوامره ويتجنب نواهيه والشخص إللي واقع في المنكرات والخطأ زي ناس ركبوا سفينة\n فعملوا قرعة عشان يشوفوا مين هيقعد على ظهر السفينة ومين هيقعد أسفل السفينة،\nفناس قعدوا على ظهر السفينة وناس قعدت أسفل السفينة،\nوكان الناس إللي أسفل السفينة كل ما يكونوا عايزين مية لازم يعدوا على الناس إللي على ظهر السفينة ،\nفقالوا:\nاحنا نعمل خرق في السفينة نخرمها يعني وناخد المية إللي احنا عايزينها وبكده مش هنؤذي الناس إللي فوقنا\nفلو هم تركوهم يعملوا خرق في السفينة كل الناس إللي في السفينة فوق وتحت هيهلكوا جميعا\nولو منعوهم من خرق السفينة كل الناس في السفينة هتنجو،\nفاللي بيعمل معصية وخطأ وبيجاهر بها وسط الناس والناس مأنكرتش عليه وسابته يعمل إللي هو عايزه بحجة كل واحد حر واحنا ملناش دعوة\nالعقاب هينزل على الجميع، وكل المسلمين إللي حوالين الشخص ده هيتحملوا نتيجة خطأه،\nلأن المعصية طول ماهي في السر لن تضر إلا صاحبها، لكن أول ما الناس تجهر بها هتضر كل المجتمع،\nشوفوا ربنا بيقول إيه:\n\" وَاتَّقُوا فِتْنَةً لا تُصِيبَنَّ الَّذِينَ ظَلَمُوا مِنْكُمْ خَاصَّةً \"\nوراجعوا قصة أصحاب السبت إللي قلناها في قصص الأنبياء\nوربنا قال للمسلمين إنه أعطاهم النصر إللي وعدهم به في البداية، لكن أول ما حصل النزاع بين الرماة وقائدهم عبد الله بن جبير وعصوا أمر رسول الله ﷺ ونظروا إلى الدنيا حصلت الهزيمة\n\"وَلَقَدْ صَدَقَكُمُ اللَّهُ وَعْدَهُ إِذْ تَحُسُّونَهُم بِإِذْنِهِ ۖ حَتَّىٰ إِذَا فَشِلْتُمْ وَتَنَازَعْتُمْ فِي الْأَمْرِ وَعَصَيْتُم مِّن بَعْدِ مَا أَرَاكُم مَّا تُحِبُّونَ ۚ مِنكُم مَّن يُرِيدُ الدُّنْيَا وَمِنكُم مَّن يُرِيدُ الْآخِرَةَ ۚ \"\n\"وَأَطِيعُوا اللَّهَ وَرَسُولَهُ وَلَا تَنَازَعُوا فَتَفْشَلُوا وَتَذْهَبَ رِيحُكُمْ \"\nفربنا بيقول لنا بطريقة عملية:\nمفيش مُحابَاة لأحد، حتى لو  كان رسول الله ﷺ إللي هو أحب الخلق إلى الله،\nفي سنن كونية هتمشي على الكل، أطعتم الله ورسوله وتركتم النزاع والفُرقة هيبقى في نصر،\nهتعصوا أوامر ربنا ورسوله وهتتخانقوا على الدنيا وكله عايز ياخد حتة من التورتة هتشوفوا هزيمة وخذلان مكنتوش تتخيلوها\n\"ذَٰلِكَ بِأَنَّ اللَّهَ لَمْ يَكُ مُغَيِّرًا نِّعْمَةً أَنْعَمَهَا عَلَىٰ قَوْمٍ حَتَّىٰ يُغَيِّرُوا مَا بِأَنفُسِهِمْ\"\nيعني بالبلدي كده طول ما الناس ماشية عالصراط المستقيم ربنا هيحفظ لهم النعم إللي عندهم، \nأول ما يغيروا حالهم من الطاعة إلى المعصية ربنا هيسلب منهم نِعمه، ومن النعم دي النصر على الأعداء،\n☆ممكن حد يسأل طب والناس إللي في النص دي ذنبها إيه،\nيعني الناس إللي ماتت بسبب《 خطأ الرماة》 ذنبهم إيه\nيجاوبنا على السؤال ده ربنا عز وجل\n\"أَمْ حَسِبْتُمْ أَن تَدْخُلُوا الْجَنَّةَ وَلَمَّا يَعْلَمِ اللَّهُ الَّذِينَ جَاهَدُوا مِنكُمْ وَيَعْلَمَ الصَّابِرِينَ \"\nمش انتم كنت بتقولوا احنا نفسنا في الشهادة، احنا نفسنا نموت في سبيل الله ، أهه الشهادة جت لكم أهه،\nومع ربنا مفيش خسارة يا جماعة\n\"وَلَقَدْ كُنتُمْ تَمَنَّوْنَ الْمَوْتَ مِن قَبْلِ أَن تَلْقَوْهُ فَقَدْ رَأَيْتُمُوهُ وَأَنتُمْ تَنظُرُونَ \"\nإللي هينتصر هيعيش في عِزة طول ماهو طائع لله، وإللي هيموت في سبيل الله هيدخل جنة عرضها السموات والأرض \nطيب وإللي هيعيش بعد الهزيمة والناس تهاجمه وتتعرض له بأذى \nده من الابتلاء\nخلونا نشوف القرآن بيقول لنا إيه\n\"ثُمَّ صَرَفَكُمْ عَنْهُمْ لِيَبْتَلِيَكُمْ \"\nيعني ربنا ابتلى الناس إللي تبقت بعد المعركة عشان يشوف المُخلص من غير المخلص، عشان الناس تبان على حقيقتها،\nالصحابة في الوقت ده مكنوش لسه يعرفوا موضوع المنافقين، \nلكن بعد الهزيمة في أُحد كله بان على حقيقته، إللي كان بيدافع ويقول أيوة احنا معاكم دلوقتي بقى شمتان وبيقول تستاهلوا إللي جرى لكم، انتم إللي عملتم في نفسكم كده لو كنتم سمعتم كلامنا مكنش حصل لكم كده\n\"الَّذِينَ قَالُوا لِإِخْوَانِهِمْ وَقَعَدُوا لَوْ أَطَاعُونَا مَا قُتِلُوا\"\nأيوة المسلمين اتهزموا في أُحد، لكن اتعلموا دروس كتير عمرهم ما كانوا هيتعلموها إلا بالهزيمة دي\nوهنشوف إزاي إن الصحابة استفادوا من خطأهم في أُحد واتعلموا الدرس ومحدش فيهم كرر نفس الخطأ تاني، وبالتالي لم يُهزموا في أي غزوة بعد كده\nالمشكلة بقى في إللي متعلمش الدرس وبيكرر نفس الخطأ ومستمر عليه \nده هيفضل في الابتلاء لحد ما يفهم الدرس ويتعلم ويبدأ يغير\n◇حاولوا تربطوا كده بين الكلام إللي قلته ده\n وبين أحوال المسلمين في الكم سنة الأخيرة بالذات، هتلاقوا تشابه كبير جدا في الأحداث، التاريخ بيعيد نفسه بس احنا إللي مش بنتعلم للأسف\nربنا قال ليهود بني قينقاع إللي اتكلمنا عنهم قبل كده:\n\"قَدْ كَانَ لَكُمْ آيَةٌ فِي فِئَتَيْنِ الْتَقَتَا \"\nالكلام ده مش ليهم هم بس، ده لينا احنا كمان عشان نتعلم،\nعلى مر التاريخ كله في آية وعبرة من فئتيتن التقتا، \nلكن للأسف احنا بنعمل زي بني قينقاع، مش بنعتبر وبنقع في نفس الخطأ بتاعهم، واحنا شايفين أحوال المسلمين عاملة إزاي\nنرجع لرسول الله ﷺ إللي كان لسه واقع في الحفرة \nومش قادر يقوم من شدة الضرب إللي تعرض له والدم إللي نزفه ﷺ والمسلمين إللي كانوا حوله بيدافعوا عنه، \nلدرجة إن امرأة من النساء إللي خرجوا مع الجيش عشان يطببوا الجرحى ويسقوهم الماء اسمها أم عمارة \n《نُسَيْبة بنت كعب》 لما لقت رسول الله ﷺ في الحالة دي ومكنش حوله ناس كثير يدافعوا عنه مسكت السيف وبقت هي إللي تحارب وتدافع عن رسول الله ﷺ، \nوأُصيبت رضي الله عنها بجراح كثيرة، ومنها إن ابن قمئة إللي ضرب رسول الله ﷺ على كتفه ،ضربها بالسيف هي كمان وعمل جرح شديد عندها فضلت تشتكي منه طول عمرها،\nوصل ثلاثين رجل من المسلمين عند رسول الله ﷺ وشافوه واقع في الحفرة والدم بينزل منه، فاستماتوا في الدفاع عنه ﷺ وبدأوا يصدوا هجمات المشركين،\nوالمشركين مش ساكتين عايزين يوصلوا لرسول الله ﷺ بأي طريقة، فبدأوا يرموا عليه السهام وهو ساقط في الحفرة\nفأبو دجانة صاحب العصابة الحمراء إللي كان أخذ سيف رسول الله ﷺ حاول يرد السهام إللي نازلة على رسول الله ﷺ زي المطر بالترس إللي معاه مقدرش\nراح نازل على طول قصاد رسول الله ﷺ وغطاه بجسمه وجعل ظهره للسهام عشان يحميه منهم،\nفظهره اتملى بالسهام وكان لابس درع لدرجة إنه بقى عامل زي القنفذ\n من كثرة السهام إللي رميت عليه رضي الله عنه\nشاف رسول الله ﷺ إن أنسب حل دلوقتي إنه ينسحب بالمسلمين من أرض المعركة عشان يعيد ترتيب أوضاعهم مرة ثانية بدل ما يعرّض المسلمين كلهم للهلاك،\nقام رسول الله ﷺ من الحفرة بمساعدة الصحابة وانسحبوا ناحية جبل أحد، فكانوا بيقاتلوا المشركين وهم بينسحبوا للجبل،\nلسه هيصعدوا على الجبل شاف أُبي بن خلف رسول الله ﷺ وجاء بسرعة على فرسه ناحية رسول الله ﷺ وهو بيقول :\nلا نجوت إن نجا..لا نجوت إن نجا! يعني يا أنا يا هو\nفالصحابة قالوا لرسول الله ﷺ:\nواحد فينا يروح يقتله يا رسول الله \nفقال لهم اتركوه\nفأول ما قرب من رسول الله ﷺ مسك رسول الله ﷺ حربة ورماه بها، فأصابته بخدش، يعني جرح بسيط جدا، ومع ذلك قعد يصرخ من الوجع وطلع يجري وهو بيقول :\nقتلني والله محمد..قتلني والله محمد\nوالمشركين مستغربين\nفقالوا له: إنت شكلك اتجننت\nمفيش حاجة فيك \nفقال لهم : هو كان قايلي في مكة إنه هيقتلني، فوالله لو بصق عليّ لقتلني\n☆يعني هو عارف ومصدق رسول الله ﷺ أهه، طيب ليه العناد بقى \nفعلا، في ناس بترمي نفسها في الهلاك وهي عارفة\nمعداش على أبي بن خلف يوم إلا وكان ميت، وأبي بن خلف هو الرجل الوحيد إللي قتله رسول الله ﷺ ولم يقتل بيده غيره ﷺ \nبعد ما انهزم المسلمون وحصل فيهم الاضطراب وقُتل سبعون من الصحابة، بدأ المشركون يُمَثّلوا بالقتلى،\nقطعت النساء آذان الرجال من المسلمين وأنوفهم وعملوها قلائد يعني سلاسل ولبسوها.\n☆ملحوظة هامة:\nالتمثيل بجثث القتلى لا يجوز في شريعة الإسلام\nالتمثيل يعني إن الشخص يقعد يقطع في أطراف الميت ويشوّه جسمه ويقطع أنفه أو أذنه،\nإلا لو الكفار عملوا كده في المسلمين، يعني لو الكفار مثلوا بقتلى المسلمين، فمُباح للمسلمين إنهم يمثلوا بقتلى الكفار على سبيل 《القصاص》 وتركه أفضل \nيقول الله عز وجل:\n\"وَإِنْ عَاقَبْتُمْ فَعَاقِبُوا بِمِثْلِ مَا عُوقِبْتُم بِهِ ۖ وَلَئِن صَبَرْتُمْ لَهُوَ خَيْرٌ لِّلصَّابِرِينَ \"\n هند بنت عتبة شافت حمزة بن عبد المطلب مقتول وهو إللي كان قتل أبوها واشترك في قتل أخوها، فنزلت عليه بالسيف تقطع فيه، شقت بطنه وقطعت أذنه وأنفه\n☆ملحوظة هااامة\nمفيش ولا حديث صحيح عن إن هند بنت عتبة أخرجت كبد حمزة رضي الله عنه وأكلت منها ولما لم تستسغها رمتها، يعني لقت طعمها وحش رمتها \nكلها أحاديث إما منكرة، أو أحاديث ضعيفة منقطعة،\nبدأ رسول الله ﷺ بالصعود على الجبل فوقفت قصاده صخرة مقدرش يعديها بسبب جراحه وتعبه،\nفجلس طلحة بن عبيد الله إللي كان مصاب بتسعة وثلاثين جرح عشان رسول الله ﷺ يطلع على ظهره ويتسلق به الصخرة، فقال له رسول الله ﷺ:\nأوجب طلحة، يعني طلحة عمل كل حاجة يقدر يعملها، وكان أبو بكر الصديق رضي الله عنه يقول لما يتذكر يوم أُحد:\nذلك اليوم كله لطلحة، يعني اليوم ده كان بتاع طلحة من إللي عمله فيه رضي الله عنهم أجمعين،\nوالصحابة بيصعدوا الجبل شافوهم خالد بن الوليد وأبو سفيان،\nفجمعوا المشركين عشان يمنعوا الصحابة من إنهم يصعدوا الجبل؛ لأنهم لو صعدوا الجبل خلاص مش هيقدروا يوصلوا لهم\nوهم عايزين يتأكدوا إن رسول الله ﷺ خلاص قُتل زي ما ابن قمئة قال ، فقال رسول الله ﷺ :\nإنهم لا ينبغي لهم أن يعلونا ،يعني مينفعش يطلعوا ورانا، لازم نمنعهم\nفكلّف رسول الله ﷺ مجموعة من أصحابه إنهم يدفعوا المشركين ويمنعوهم من طلوع الجبل وراء المسلمين وكان على رأس المجموعة عمر بن الخطاب رضي الله عنه،\nفقاتلوا المشركين قتالا شديدا لحد ما استطاعوا إنهم يمنعوهم من الصعود للجبل واستطاع رسول الله ﷺ وإللي كانوا معاه إنهم يختفوا في الجبل\n☆ممكن حد يسأل ، طيب هو كده مش يبان إن رسول الله ﷺ بيضحي بأصحابه عشان يحافظ على حياته\n◇أولا:\nالصحابة كانوا بيحبوا رسول الله ﷺ حب ملوش مثيل، كانوا يتمنوا إنهم يفدوه بأرواحهم وأموالهم وكل غالي، كان هو أغلى حاجة في حياتهم،\n أغلى من آبائهم وأبنائهم ، والطبيعي إن لما إنسان بيحب حد بيخاف عليه من أقل حاجة وبيحزن لو إللي بيحبه حصل له شيء، وبيكون نفسه يبقى مكانه عشان ميتألمش،\n كذلك كان الصحابة مع رسول الله ﷺ\nكانوا بيقدموا أرواحهم وأموالهم وكل غالي عشان يحموا رسول الله ﷺ بطيب نفس، النساء والرجال على السواء.\n◇ثانيا:\nفي كل قوانين الدنيا المتعارف عليها من قديم الأزل: \nيجب على الجنود حماية قائد الجيش\nلأن القائد له خصوصية غير باقي الجنود؛ لأن القائد بيكون مميز فهو إللي بيخطط للمعركة وبيعرف يديرها إزاي ودوره مهم جدا،\nفلو قُتل القائد أو أُسر، الجيش هيهزم هزيمة نفسية وعسكرية\nوفي معارك المسلمين بصفة عامة أو أي معارك لغير المسلمين هنلاقي إنهم بيدوروا على القائد عشان يقتلوه،\nلأن مجرد ما القائد مات انتهت المعركة بالهزيمة إلا لو واحد تاني تولى القيادة وعرف يقود الجيش ودي بتبقى حالات نادرة\nفالأصل إن لازم قائد الجيش يكون له حماية خاصة،\nفتخيلوا بقى لما القائد يكون رسول الله ﷺ إللي مش مجرد قائد لمعركة، ده حامل النور للبشرية،\nفهم لما بيحموه مش بس بيحموا شخصه ﷺ، ده بيحموا الدين، بيحموا دعوة الحق،\nوطبيعي إن رسول الله ﷺ يطلب من أصحابه إنهم يساعدوه في صد هجوم الكفار، ويُعين بعضهم بعض، ومش احنا قلنا من شوية إن المصلحة العامة للمسلمين أهم من المصالح الشخصية\nوالسبب الرئيسي في قيام أمة الإسلام هو التضحية إللي الصحابة ضحوا بها، سواء تضحية بالأموال أو الأرواح،\nأمة الإسلام قامت على دماء المسلمين،\nعشان كده احنا كمسلمين مش بيهمنا بيموت مننا أد إيه في مقابل قيام دولة الإسلام،\nوهو ده إللي الصحابة عملوه، فاكرين لما اتكلمنا المرة إللي فاتت عن السبعة من الأنصار إللي دافعوا عن رسول الله ﷺ واحد واحد وقُتلوا جميعا،\nلو قلنا إن الأول مكنش يعرف إنه هيموت، والثاني قال يمكن أنا أقدر انتصر، طيب الثالث والرابع لحد السابع،\nالسابع شاف ستة من أصحابوا قُتلوا ،كان من الأَوْلى إنه يحافظ على حياته لو كانت مهمة في نظره،\nلكن في مقابل الدفاع عن رسول الله ﷺ إللي بيتمثل فيه قيام دولة الإسلام يبقى مفيش مشكلة، وكأن لسان حالهم يقول: نحن أمة لا تُبالي بالدماء \n《إللي عايز تفصيل أكبر في الرد على السؤال ممكن يراجع موقع الإسلام سؤال وجواب\n لما المسلمين قدروا يمنعوا جيش المشركين من إنهم يطلعوا الجبل المشركين تفاجؤوا\nبقى الناس إللى احنا كنا خلاص هزمناهم وضربناهم هم إللي بينزلونا من على الجبل دلوقتي\nومع ذلك سبحان الله، قريش بدأت تسحب نفسها ولم تُصمم إنها تطلع الجبل وراء المسلمين، قالوا بس خلاص كفاية إللي احنا عملناه فيهم،\nفحب أبو سفيان إنه يتأكد إذا كان رسول الله ﷺ فعلا قُتل ولّا لأ زي ما ابن قمئة قال، فقال للمسلمين:\nأفيكم محمد\nيعني محمد ﷺ لسه عايش، فرسول الله ﷺ أشار للصحابة بإنهم ميردوش على أبو سفيان فسكتوا،\nفقال أبو سفيان : أفيكم ابن قحافة\nفأشار لهم رسول الله ﷺ إنهم ميردوش والصحابة ساكتين،\nفسأل أبو سفيان : أفيكم عمر\nفمحدش من الصحابة رد، ففرح أبو سفيان وقال :\nخلاص كده الثلاثة دول ماتوا وارتحنا منهم\nفعمر بن الخطاب رضي الله عنه مقدرش يمسك نفسه\nحس بغيظ وشماتة فمقدرش يسكت فرد عليه وقال له:\nيا عدو الله! إللي انت ذكرتهم دول أحياء وربنا أبقى على ما يسوؤك\nيعني ربنا أبقى على حياة إللي يضايقك ويحرق دمك\n☆إيه ده \nهو كده مش يبقى عمر عصى أمر رسول الله ﷺ بإنهم ميردوش على المشركين زي ما الرماة عصوا أمر رسول الله ﷺ \nالوضع مختلف طبعا، أَمْر رسول الله ﷺ للرماة كان تشريعي واضح وصريح وأكد عليه أكثر من مرة، مفهوش أي مجال للاجتهاد لأن ضرره كارثي، أما موقف عمر بن الخطاب هنا مختلف،\nرسول الله ﷺ لم يُلزمهم ويؤكد عليهم زي ما عمل مع الرماة، هو كان أمر اجتهادي من رسول الله ﷺ إن الأَوْلى إنهم ميردوش على المشركين،\nلكن لما المشركين بدأوا يشمتوا ويغيظوا المسلمين عمر ماستحملش، ورسول الله ﷺ لم يعاتبه ويقول له اسكت،\nبالعكس شوفوا إيه إللي حصل بعد كده\nأبو سفيان لما سمع كلام عمر اتصدم، لأنه كان وصل له إن رسول الله ﷺ كان خلاص قُتل، فقال له :\nناشدتك الله يا عمر، هو محمد فعلا حي ولا قتلناه\nفقال له عمر : بل حي\nفقال أبو سفيان: أنت عندي أصدق وأبر من ابن قمئة\n☆المشركين كانوا بيحترموا المسلمين، يعني هم كانوا بيقاتلوهم ويعذبوهم، لكن في داخلهم كل الاحترام للمسلم إللي بيدافع عن عقيدته ومبادئه وتضحيته في سبيل دينه،\nعشان كده أبو سفيان صدق عمر، وكان عنده أصدق من صاحبه ابن قَمئة\nأبو سفيان طبعا اتغاظ إن رسول الله ﷺ والوزيرين بتوعه لسه عايشين\n فحب يرد الغيظ ده للمسلمين قال لهم :\nقد كان فيكم مُثلة لم آمر بها ولم تسُؤني \nيعني الجثث بتاعة أصحابكم حصل فيها تمثيل، وأنا مأمرتش بكده، بس أنا عادي مزعلتش يعني، \nمع إن العرب أصلا من طبيعتهم إنهم لا يمثلوا بالجثث، بس عادي يعني مادام مع المسلمين يبقى مفيش مانع نكسر القاعدة ونخالف كل قوانينا\nأبو سفيان حب يحس بنشوة الانتصار فقال بصوت عالي: \nأُعْلُ هُبل! يعني بيعظمه وإنه هو إللي نصرهم،\nفسكت الصحابة وهم متضايقين وحاسين بالقهر، هو أه الهزيمة مش بسببهم، بس الهزيمة شاملة الكل، \nأقول لكم مثال عشان اقرب لكم المعنى\nعارفين لما تكون واحدة لابسة نقاب أو واحد بلحية وتلاقيه عمل خطأ والناس بقى تقعد تتكلم بكلام يغيظ ويحرق الدم،\nإنتِ كمنتقبة أو الرجل الملتحي هيحس بضيق، \nمش هو إللي عمل الخطأ لكن الكلام بيؤذيه لأنه زي ما بنقول في مركب واحدة، أو بمعنى أصح زي ما قلنا في البداية في سفينة واحدة\nفقال لهم رسول الله ﷺ:\nألا تجيبوه؟\nقالوا: نقول إيه يا رسول الله\nفقال لهم : قولوا الله أعلى وأجلّ!\n☆رسول الله ﷺ بيعلم الصحابة وبيعلمنا إن مش عشان حصل للمسلمين هزيمة مادية يبقى ده مانع من الفخر بعقيدتكم كمسلمين\nفقالوا : الله أعلى وأجل \nفرد عليهم أبو سفيان : لنا العُزّى ولا عُزّى لكم\nفقال لهم رسول الله ﷺ : ألا تجيبوه؟\nفقالوا : نقول إيه يا رسول الله\nقال : قولوا الله مولانا ولا مولى لكم، فقال الصحابة : \nالله مولانا ولا مولى لكم\nفأبو سفيان مسكتش \nقال: يوم بيوم بدر\nيعني زي ماهزمتونا في بدر هزمناكم في أحد\nفقال رسول الله ﷺ للصحابة إنهم يقولوا: \nلا سواء \n يعني مفيش مقارنة، قتلانا في الجنة وقتلاكم في النار\nفانسحب أبو سفيان من أرض المعركة ولم يقعد فيها لحظة واحدة، وكأنه كان عايز يهرب \nطيب هل كده يعتبر المشركين انتصروا فعلا في غزوة أحد؟\nوالمسلمين هيعملوا إيه عشان يخرجوا من الأزمة دي ورسول الله ﷺ لسه لحد دلوقتي بينزف والدم مش راضي يقف\nده إللي هنعرفه الجزء الجاي إن شاء الله \n♡"}, {"n": 102, "l": "الجزء 76 | هل فعلا انتصر المشركون في غزوة احد", "u": "https://www.facebook.com/groups/710210019782034/permalink/812770912859277/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_السادسة_والسبعون\n#هل_فعلا_انتصر_المشركون_في_غزوة_أحد\nوقفنا المرة إللي فاتت عند أبو سفيان لما أخذ جيش المشركين بعد انتصارهم في غزوة أحد على المسلمين واتجهوا راجعين لمكة،\nالسؤال هنا، هل فعلا جيش المشركين انتصر على جيش المسلمين في معركة أحد\nتعالوا كده نشوف:\n◇قريش لم تأخذ أسيرا واحدا من المسلمين في غزوة أحد،\nفي حين إن المسلمين أسروا في غزوة بدر من قريش سبعين أسير\n◇قريش لم تأخذ غنائم من المسلمين، في حين إن المسلمين أخذوا غنائم كثيرة من المشركين في غزوة بدر\n◇قريش لم تدخل المدينة المنورة مع إنها كانت قريبة جدا منها ومكنش في المدينة جيش يحميها، وكمان لم تسيطر على مكان المعركة، ده حتى مقعدوش في مكان المعركة عشان يعلنوا للناس إنهم انتصروا\nفاكرين لما في بدر قالوا إننا هنقعد في بدر لحد ما كل العرب يسمعوا بنا، أهه المفروض كانوا عملوا كده في المعركة دي على أساس انهم انتصروا\nلكن دول ما صدقوا، أول ما المعركة خلصت وقتلوا بعض المسلمين راحوا ماشيين على طول\nفي حين إن رسول الله ﷺ زي ما شفنا أكثر من مرة إنه لما كان بيخرج في غزوة كان بيقعد في مكانها بعد نهايتها ثلاثة أيام على الأقل عشان الخبر يوصل للناس ويعرفوا قوة المسلمين\n◇المشركين لم يقتلوا قائد الجيش إللي هو رسول الله ﷺ ولا الوزيرين بتوعه، يعني دولة الإسلام زي ما هي\nفين بقى هزيمة المسلمين وانتصار المشركين عليهم\nغزوة أحد مكنتش هزيمة، لكن كانت زي ما سماها القرآن : قَرْح، يعني جراح شديدة، مقتل أكثر من سبعين رجل من المسلمين\n\"إِن يَمْسَسْكُمْ قَرْحٌ\"\n☆طيب هو مش مقتل المسلمين في سبيل الله ده حاجة كويسة، ليه بقى ربنا قال إنها جراح، وفي آية تانية سماها مصيبة \n\"أَوَلَمَّا أَصَابَتْكُم مُّصِيبَةٌ قَدْ أَصَبْتُم مِّثْلَيْهَا قُلْتُمْ أَنَّىٰ هَٰذَا ۖ قُلْ هُوَ مِنْ عِندِ أَنفُسِكُمْ ۗ إِنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ\"\nمقتل المسلمين في سبيل الله حاجة جميلة جدا وهي اصطفاء من الله عز وجل ونعمة زي ما قال:\n\"وَيَتَّخِذَ مِنكُمْ شُهَدَاءَ\"\nلكن المصيبة إنهم قُتلوا بسبب خطأ بعض المسلمين، إللي كان سببه حب الدنيا إللي دخل في قلوب بعضهم وهم الرماة وأدّى إنهم يخالفوا أمر رسول الله ﷺ، \nلكن لو كانوا قُتلوا وهم بيعملوا إللي عليهم وبيحاربوا زي ما كانوا بيحاربوا في بدر وأخذوا بكل أسباب النصر ومع ذلك ماتوا شهداء فهنا مفيش مشكلة،\nفالقرآن كان بيتكلم عن مصيبة حب الدنيا إللي دخلت في قلوب بعضهم وأدت لمقتل السبعين من المسلمين\nوربنا قال:\n\"مِنكُم مَّن يُرِيدُ الدُّنْيَا وَمِنكُم مَّن يُرِيدُ الْآخِرَةَ ۚ\"\nعبد الله بن مسعود فاكرينه\nإللي طلع فوق صدر أبو جهل وقتله، \nلما نزلت آية :\n\"مِنكُم مَّن يُرِيدُ الدُّنْيَا وَمِنكُم مَّن يُرِيدُ الْآخِرَةَ ۚ\"\nقال : والله متخيلتش إن في حد فينا يريد الدنيا لحد ما نزلت هذه الآية \nكان مفكر إن الناس كلها زيه همها الآخرة،\nودي من الحِكم العظيمة إللي استفادها المسلمون بعد مصيبة أُحد، إنهم يعرفوا خطورة حب الدنيا \nاحنا دلوقتي مع رسول الله ﷺ بقالنا حوالي سبعة عشرة سنة، ثلاثة عشر سنة في مكة وثلاثة في المدينة،\nخلال السنين دي كلها كان رسول الله ﷺ بيحذر الصحابة من الدنيا، \nوكان يقول لهم:\n \" إنَّ الدُّنْيا حُلْوَةٌ خضِرَةٌ، وإنَّ اللَّهَ مُسْتَخْلِفُكُمْ فِيهَا. فينْظُر كَيْفَ تَعْمَلُونَ. فَاتَّقوا الدُّنْيَا\"\nيعني الدنيا جميلة وحلوة وربنا هيجعلكم خلفاء فيها يعني هيمكّن لكم في الأرض ويشوف هتعملوا إيه بعد التمكين ده،\nفخافوا من الدنيا وابعدوا عنها\nوحتى القرآن نفسه قليل جدا لو عدى منه صفحة أو صفحتين ومنشفش فيه تحذير من الدنيا،\nفلما تحصل مصيبة زي مصيبة أُحد كده والقرآن يتكلم عنها وكل ما يقرأوا القرآن يتذكروا إللي حصل في أحد،\nتعتقدوا إنهم ممكن ينسوا في يوم من الأيام إن حب الدنيا كان سبب في مقتل أصحابهم وسبب في الآلام إللي حصلت لرسول الله ﷺ إللي كانوا بيحبوه أكثر من أي حاجة في حياتهم\nفكل ما كان الأمر شديد على النفس ومؤلم لها كان الدرس إللي الإنسان بيتعلمه منها أكبر وميتنساش أبدا\nولو نظرنا لحياتنا هنلاقي إن كل ما كانت المشاكل إللي بنمُر بيها شديدة على نفوسنا كل ما كان أثرها أكبر في حياتنا،\nطبعا للي يفهم المعنى ويأخذ العبرة\nلأن في ناس عايشين في كوارث ومش عارفين السبب وبيرموا اللوم على ربنا وخلاص، والمشكلة من عندهم أصلا\nبعد ما انتهت معركة أحد كان المسلمون إللي فروا من أرض المعركة في البداية بعد إشاعة مقتل رسول الله ﷺ  وصلوا المدينة وأخبروا أهل المدينة باللي حصل لجيش المسلمين وإن رسول الله ﷺ قُتل،\nفالنساء قعدت تبكي وتصرخ واتقلبت المدينة، مكنش لسه اتحرم الصراخ على الموتى ساعتها\nفاطمة بنت رسول الله ﷺ لما وصل لها الخبر، خرجت مع مجموعة من النساء واتجهوا لمكان المعركة،\nعشان يساعدوا المسلمين المصابين ويتأكدوا من الخبر،\nفالمسافة بين المدينة وجبل أحد مش بعيدة ثلاثة أميال ونصف، يعني تقريبا خمسة كيلو ونصف \nوصلت النساء وكانوا تقريبا أربعة عشرة امرأة في الوقت إللي المشركين انسحبوا فيه من أرض المعركة،\nعرفت فاطمة إن رسول الله ﷺ لسه على قيد الحياة فأول ما شافت رسول الله ﷺ حضنته، وشافت الدم يسيل من وجهه ورأسه ﷺ،\nقعدت تغسل الدم بالماء، لقت إن الماء بيزوّد الدم، فأخذت قطعة من حصير وحرقتها لحد ما بقت رماد، تراب يعني ووضعته على الجرح زي الكمادات كده فتوقف الدم،\nوكان رسول الله ﷺ يقول وفاطمة تغسل الدم عنه :\nكيف يُفلح قوم فعلوا هذا بنبيهم؟!\nيعني إزاي ناس بعد كل إللي عملوه مع نبيهم ده هيفلحوا،\nقالها وهو كان يائس من هدايتهم بعد كل إللي عملوه ده،\nزي مثلا لما بنشوف واحد غرقاااان في الضلال والمعاصي والفسوق وممكن حتى الكفر ونقول : إزاي واحد زي ده ممكن يُسلم أو ينصلح حاله\nفربنا قال لرسول الله ﷺ في القرآن وطبعا الكلام لنا:\n\"لَيْسَ لَكَ مِنَ الْأَمْرِ شَيْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَالِمُونَ \"\nيعني ملكوش دعوة، ربنا يتوب عليهم أو يعذبهم، دي مش بتاعتكم، إنتم عليكم الدعوة وفقط ملكوش إنكم تحكموا على الناس\nفلما نزلت الآية دعا رسول الله ﷺ:\n\"اللهم اهدِ قومي فإنهم لا يعلمون\"\n نزل رسول الله ﷺ من على جبل أُحد عشان يشوف القتلى من المسلمين ويدفنهم، وكان عرف إن في ناس أخذوا قتلاهم وراحوا يدفنوهم في المدينة فأرسل إليهم إنهم يرجعوا القتلى عشان يُدفَنوا في أُحد لأن الأرض إللي ماتوا عليها هتشهد لهم عند الله إنهم ما ماتوا إلا لله،\nمَشى رسول الله ﷺ في أرض المعركة وبدأ يشوف القتلى من أصحابه، عايزاكم تتخيلوا مشاعر رسول الله ﷺ في الوقت ده كانت عاملة إزاي، ما هو بشر زينا بالضبط، \nتخيلوا مشاعره وهو شايف مصعب بن عمير وإيديه الاثنين مقطوعة،\nاحنا لما بيموت لنا واحد عزيز بنحبه بنبقى زعلانين جدا ومش متخيلين إزاي هنكمل الحياة من غيره،\nفما بالكم لما يكون واحد زي مصعب بن عمير، أول سفير في الإسلام، من أوائل المسلمين، من أكثر الناس ابتلاء في الله،\nوكانت هدومه إللي لابسها مش مكفياه،\nلو غطوا رجله ظهرت رأسه ولو غطوا رأسه ظهرت رجله،\nوكان مصعب فقير مكنش عنده إللي يتكفن فيه،\nشاف رسول الله ﷺ عبد الله بن حرام إللي بايعه في بيعة العقبة الثانية ،أبو جابر إللي قال له إني أرى أكون في أول من يُقتل من المسلمين، ذكريات بتعدي على رسول الله ﷺ، \nوكان جابر بن عبد الله بن حرام جاء لأرض المعركة بعد ما خلصت فلما شاف أبوه قُتل قعد يبكي، كان يشيل الغطاء من على وجهه وينظر له ويغطيه ويبكي،\nويشيل الغطاء وينظر لأبيه ويغطيه تاني ويبكي، والصحابة بيقولوا له متعملش كده ورسول الله ﷺ شايفه ولم ينهاه زي الصحابة،\nوكان من بين القتلى عمرو بن الجموح الأعرج إللي قال لرسول الله ﷺ إنه عايز يطأ بعرجته الجنة،\nلما رآه رسول الله ﷺ قال :\nلعلّي أنظر إليك تمشي برجلك هذه صحيحة في الجنة.\nيعني ربنا حقق له أمنيته بإنه رزقه الشهادة وأدخله الجنة  وأبدله قدما صحيحة بدل القدم العرجاء\nوأمر رسول الله ﷺ إن عبد الله بن حرام وعمرو بن الجموح يُدفنوا مع بعض عشان هم كانوا أصحاب في الدنيا متحابين في الله،\nوكان في وقت الدفن يقدم أكثرهم حفظا للقرآن،\nشاف رسول الله ﷺ حنظلة بن أبي عامر مقتول وعليه أثر الماء فقال للصحابة غسلته الملائكة، وبعدين أدار وجهه ﷺ عنه،\nفسأله الصحابه ليه يا رسول الله أَدرت وجهك عنه، فقال رسول الله ﷺ : إن معه الآن زوجتاه من الحور العين،\nرسول الله ﷺ كان عايز يعرف سبب تغسيل الملائكة لحنظلة فأرسل لزوجته جميلة بن عبد الله بن أبي بن سلول يسألها، فقالت إنه كان على جنابة، ولما سمع منادي الجهاد خرج بسرعة ولم يغتسل.\nطلب رسول الله ﷺ من زيد بن ثابت إنه يبحث له عن سعد بن الربيع هل هو حي ولا قُتل،\n☆سعد بن الربيع إللي رسول الله ﷺ آخى بينه وبين عبد الرحمن بن عوف، فقال سعد لعبد الرحمن إنه هيقسم ماله نصفين ويعطيه واحدة من زوجاته، فاكرينه\nرسول الله ﷺ عايز يعرف هو فين، فقال لزيد لو قابلته فقل له رسول الله ﷺ يقول لك: كيف تجدك، بيسألك عن حالك، عامل إيه،\nفقام زيد بن ثابت يبحث عنه لحد ملقاه في القتلى في آخر رَمَق، يعني خلاص في النفس الأخير ومضروب في جسمه سبعين ضربة بالسيوف والرماح والسهام،\nفقال له زيد:\nيقول لك رسول الله ﷺ: كيف تجدُك، فقال سعد:\nوعلى رسول الله ﷺ السلام، أنا أجد ريح الجنة، يعني أنا شامم ريحة الجنة، وقل لأصحابي من الأنصار:\nلا عُذر لكم عند الله إن خُلِص إلى النبي وفيكم عين تَطْرِف، ومات مباشرة رضي الله عنه،\nالإنسان في وقت موته بيظهر على حقيقته، بيظهر فعلا إللي كان عايش عليه،\nفاللي كان عايش على طاعة ربنا هيموت على طاعة ربنا، وإللي كان عايش لنصرة الله ورسوله هيموت وهمه نصرة الله ورسوله،\nسعد بن الربيع وصيته مكنتش عن أمواله ولا زوجاته، كانت عن رسول الله ﷺ بيقول لقومه:\nملكوش عذر قصاد ربنا لو رسول الله ﷺ حصل له حاجة وإنتم لسه فيكم واحد عايش، يعني كلكم تَفنوا حياتكم وميتبقاش حتى واحد في مقابل إنكم تحموا رسول الله ﷺ\nالصحابة كانوا بيحبوا رسول الله ﷺ حب ملوش مثيل فعلا، وحبهم كان فعلا حقيقي مش مجرد كلام،\nمش زي دلوقتي ييجي واحد ولا واحدة تقول لك أنا بحب الرسول وهي غرقانة في كل حاجة رسول الله ﷺ نهى عنها،\nسماع أغاني وعمل حواجب وغيبة ونميمة وتبرّج و....و...\nالحب اتّباع، الحب إن الإنسان يقدم رغبة إللي بيحبه على رغبته هو،\nمش بتشوفوا بنات تقول لكم أنا عايزة أعمل كذا بس خطيبي مش راضي وتسمع كلامه، مع إنه أصلا ملوش كلمة عليها\nبس بتسمع كلامه عشان بتحبه حتى لو مش مقتنعة بالكلام، \nهو ده على الأقل خااالص الحب إللي المفروض نحبه لرسول الله ﷺ،\nوإلا فاحنا لازم نحبه حتى أكثر من انفسنا، قال رسول الله ﷺ :\n\"لا يُؤْمِنُ أَحَدُكُمْ حَتَّى يَكُونَ اللَّهُ وَرَسُولُهُ أَحَبَّ إِلَيْهِ مِمَّا سِوَاهُمَا\"\nوقال:\n\"لا يؤمن أحدكم حتى أكون أحب إليه من والده وولده والناس أجمعين\"\nوعمر بن الخطاب لما قال لرسول الله ﷺ : \nأنت أحب إليّ من كل شيء إلا من نفسي، قال له رسول الله ﷺ: لا يا عمر حتى أكون أحب إليك من نفسك\nعمر مقلوش طيب أنا مقدرش، الموضوع صعب، طيب سيبني أفكر، إزاي أكثر من نفسي يا رسول الله، لا يكلف الله نفسا إلا وسعها...محصلش \nعمر على طول قال له نفس اللحظة، فأنت يا رسول الله أحب إلي من نفسي، فقال له رسول الله ﷺ: الآن يا عمر، يعني دلوقتي اكتمل إيمانك، \n◇السؤال بقى: هو رسول الله ﷺ بيمثل لنا إيه في حياتنا؟\nهل هو فعلا أحب إلينا من أي حاجة في الدنيا، من أزواجنا ، من عيالنا، من أمهاتنا ، من أبائنا ، من أنفسنا؟\nمحدش يستعجل الإجابة، الإجابة الصحيحة هتظهر لكم بطريقة عملية لما يتعرض عليكم أمر من أوامر رسول الله ﷺ في مقابل أوامر ناس تانية أو في مقابل رغباتكم الشخصية، شوفوا إنتم بتقدموا كلام مين، \nمين رقم واحد في حياتكم وإللي مستعدين تخسروا أي حد عشانه، هل هو رسول الله ﷺ ولا مين؟\nقال رسول الله ﷺ  في حديث صححه بعض العلماء:\n\"لا يُؤمن أحدكم حتى يكون هواه تَبعا لما جئتُ به\"\nيعني حتى رغباتنا لازم تكون مع شرع الله وطاعته مش مع معصية الله ومخالفة أمره\nاستمر رسول الله ﷺ يشوف القتلى وكان معاه بعض الصحابة ماشيين معاه بيشوفوا القتلى، وكان منهم سعد بن أبي وقاص، \nفسعد عمال بيدور في القتلى على واحد من الصحابة اسمه عبد الله بن جحش،\n☆وعبد الله بن جحش هو ابن عمة رسول الله ﷺ أخو زينب بنت جحش إللي هيتزوجها رسول الله ﷺ بعدين زي ما هنشوف إن شاء الله،\nوهو قائد المسلمين في سرية نخلة إللي حصلت في أواخر شهر رجب من السنة الأولى للهجرة وحصلت أزمة ساعتها فاكرين\nليه بقى سعد بن أبي وقاص كان بيدور عليه\nتعالوا نرجع لقبل بداية معركة أُحد خالص والمسلمين لسه بيستعدوا للقتال،\nقال عبد الله بن جحش لسعد ما تيجي نروح في جنب لوحدنا كده ندعي ربنا، فوافق سعد وراحوا بعيد عن الجيش ودعوا، قال سعد: \nيارب لما تبدأ المعركة خليني أقابل رجل من المشركين قوي جدا أقاتله ويقاتلني ثم تنصرني عليه وأقتله وآخذ سَلْبه، يعني أغراضه من درع وسيف وهكذا،\n قال عبد الله بن جحش:\nيارب لما تبدأ المعركة خليني أقابل رجل من المشركين قوي جدا أقاتله ويقاتلني، فيقتلني ويقطع أذني وأنفي، ولما أقابلك تسألني : يا عبد الله مين قطع أنفك وأذنك؟ فأقول فيك يارب، فتقول صدقت،\nفسعد بن أبي وقاص عايز يشوف هل فعلا حصل إللي كان يتمناه عبد الله بن جحش ولّا لأ،\nفرآه سعد مقتولا وأنفه وأذنه مقطوعتين ومعلقتين في خيط فقال :\nإن دعوة عبد الله بن جحش كان أحسن من دعوتي، وإني لأرجو أن يعطيه الله ما سأل يوم القيامة\nرسول الله ﷺ شاف وسط القتلى حمزة بن عبد المطلب عمه وأخوه من الرضاعة\nشافه بطنه مفتوحة وأنفه وأذنه مقطوعين، قعد ينظر إليه ، ومكنش في منظر أوجع لقلب رسول الله ﷺ من منظر حمزة رضي الله عنه وهو مقتول كده\nصدمة شديدة جدا لرسول الله ﷺ لدرجة إنه قال : لن أصاب بمثلك أبدا، \nيعني مفيش مصيبة ممكن تحصل هتكون أشد علي من مصيبتي فيك، \nفي اللحظة دي رسول الله ﷺ شاف امرأة جاية بسرعة فلما قربت من مكان القتلى وإللي كان فيه حمزة قال رسول الله ﷺ : المرأة المرأة، يعني امنعوا المرأة إنها تيجي وتشوف منظر القتلى، \nلأن النساء بصفة عامة متستحملش إنها تشوف منظر زي ده، وخصوصا لو كان أحد من أقاربها زي أخوها،\nفالزبير بن العوام كان واقف مع رسول الله ﷺ فقال :\nفتوسّمت أنها أمي صفية، يعني توقع إن المرأة دي هي أمه صفية، فخرج إليها يلحقها قبل ما توصل للقتلى ووقفها،\nفراحت ضربت الزبير في صدره، وقالت له: \nاوعى من طريقي، وكانت امرأة قوية شديدة رضي الله عنها\nفقال لها: \nده رسول الله ﷺ هو إللي قال إنك متروحيش ناحية القتلى، فوقفت مكانها، وأخرجت ثوبين كانوا معاها وقالت له:\nأنا عرفت إن أخي حمزة قُتل، خذ الثوبين دول كفنوه فيهم.\n☆صفية تبقى عمة رسول الله ﷺ وإللي مات ده أخوها وعايزة تشوفه، ومع ذلك وقفت وسمعت كلام رسول الله ﷺ  مقلتش إزاي مشفش أخويا قبل ما يندفن وقعدت تجادل وتصمم إنها تشوفه، جالها الأمر خلاص انتهى.. سمعنا وأطعنا،\nوده يعلمنا مهما كانت مشاعرنا فيها حزن شديد أو حتى فرحانين يجب إنها متخرجش عن إطار شرع ربنا\nأخذ الزبير الثوبين وراح لرسول الله ﷺ عشان يكفنوا حمزة،\nفلما أرادوا إنهم يكفنّوه ، لقوا جنبه رجل من الأنصار ملوش كفن واتعمل فيه زي ماتعمل في حمزة بالضبط من التمثيل بجثته،\nفاستحى الصحابة ومبقوش مرتاحين، إزاي يكفنوا حمزة في ثوبين، والأنصاري ملوش كفن\nفقالوا إنهم يكفنوا كل واحد في ثوب من الثوبين.\n☆ والشهداء إللي بيموتوا في معارك ضد الكفار لا يُغسّلوا ولا يُصلى عليهم ويُكفنوا في ثيابهم إلا لو ملابسهم تقطعت، أو أُخذت ثيابهم فيُؤتى لهم بثياب يُكفنوا فيها،\n وده القول الراجح من جمهو أهل العلم ، لأن الصلاة على الميت هي شفاعة له، والشهيد يُكفر عنه كل شيء إلا الدين، وبيشفع في سبعين من أهله فمش محتاج شفاعة أصلا\nبدأ رسول الله ﷺ في دفن الموتى، دفن حمزة بن عبد المطلب مع ابن أخته عبد الله بن جحش، ودفن عبد الله بن حرام زي ما قلنا مع عمرو بن الجموح، والموقف صعب ومؤلم لرسول الله ﷺ وهو بيدفن أصحابه واحد وراء الثاني\n☆ممكن حد يسأل بعد ما شاف إللي حصل لرسول الله ﷺ من آلام نفسية وجسدية هو ليه ربنا خلى رسول الله ﷺ يتعرض للأذى ده، هو رخيص عند ربنا يعني \nهو مش قال لرسوله: \" فَإِنَّكَ بِأَعْيُنِنَا\" فين بقى\nاحنا قلنا كتير إن رسول الله ﷺ هو القدوة للبشرية كلها،\nفعشان لما أي إنسان يتحط في موقف فيه ألم وأذى يتذكر إللي حصل مع رسول الله ﷺ ويصبر،\nوربنا لما قال لرسول الله ﷺ فإنك بأعيننا، مقلوش إنه هيعيش مبسوط ..مرتاح..مش بيتعرض للأذى أو مشاكل أو إني هجاملك وتفسد المقاييس والسنن الكونية في إن تنصروا الله ينصركم، \nلكن ربنا بيُقيم برسول الله ﷺ الحق والمِلّة العَوْجاء، شوفوا أول الآية ربنا بيقول إيه:\n\"وَاصْبِرْ لِحُكْمِ رَبِّكَ فَإِنَّكَ بِأَعْيُنِنَا\" \nبيقول له اصبر على إللي هتواجهه، الابتلاء موجود وسُنن ربنا لا تُحابي أَحد، فزي ما حصل مع رسول الله ﷺ هيحصل مع غيره\nوزي ما رسول الله ﷺ اتعامل مع المشاكل وحلها بطريقته، لازم احنا كمان نعمل زيه،\nإزاي بقى رسول الله ﷺ خرج من الأزمة دي، ويا ترى هيعمل إيه في شماتة المنافقين واليهود في المدينة\nده إللي هنعرفه الجزء الجاي إن شاء الله \n♡"}, {"n": 103, "l": "الجزء 77 | الخروج من مصيبة احد", "u": "https://www.facebook.com/groups/710210019782034/permalink/812771322859236/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية_\n#الحلقة_السابعة_والسبعون\n#الخروج_من_مصيبة_أحد\nاتكلمنا المرة إللي الفاتت عن إللي حصل مع رسول الله ﷺ من أذى جسدي وأذى نفسي لما شاف أصحابه مقتولين وجثثهم قد مَثّل بها المشركون، \nوبدأ يدفن شهداء أحد، وقلنا إنه كان بيضع في القبر الواحد كل اثنين مع بعض، وكان بيُقدّم في القبر إللي حافظ قرآن أكثر، وبيضع كل اثنين كانوا متحابين في الله قبل ما يموتوا مع بعض،\nوكان ﷺ يقول عن الشهداء: \n\"أشهد على هؤلاء، ما من مجروح جُرح في الله عز وجل إلا بعثه الله يوم القيامة وجُرحه يَدمي، اللون لون دم، والريح ريح مِسك\" \nيعني الشهيد ربنا هيبعثه زي ماهو بجراحه والدم بينزف منه، والناس كلها هتبقى شايفة دمه سائل لكن ريحة الدم هتكون زي ريحة المسك\nمن ضمن الشهداء إللي رسول الله ﷺ دفنهم كان خَيْثَمة بن الحارث، وخيثمة ده له قصة،\nفي غزوة بدر كان عايز يخرج مع رسول الله ﷺ وابنه سعد كان عايز يخرج هو كمان، فخيثمة قال لابنه :\nآثرني بالخروج، وخليك انت مع النساء\nيعني خليني أنا إللي أخرج مع رسول الله ﷺ وانت اقعد ارعى النساء من بعدي، فابنه قال له : \nلو كانت حاجة غير الجنة كنت آثرتك بها\nفاستهموا، يعني عملوا قُرعة بينهم فخرج سهم سعد بن خيثمة، وقُتل في بدر شهيدا رضي الله عنه،\nأبوه خيثمة شافه في المنام قبل غزوة أحد بيوم وقال له:\nالْحَق بنا يا أبتِ، يعني تعال لنا في الجنة، فخرج مع رسول الله ﷺ في غزوة أحد وقُتل شهيدا رضي الله عنه، \nودفنه رسول الله ﷺ، \nبعد ما رسول الله ﷺ انتهى من دفن الموتى، قال لأصحابه إنهم يصطفوا وراءه عشان يدعو ويثني على الله، قال :\n\"اللهم لك الحمد كله، اللهم لا قابض لما بسطت، ولا باسط لما قبضت، ولا هادي لمن أضللت،\n ولا مُضل لمن هديت، ولا معطي لما منعت، ولا مانع لما أعطيت، ولا مُقرّب لما باعدت، ولا مُبعد لما قربت ، اللهم ابسط علينا من بركاتك ورحمتك وفضلك ورزقك، \nاللهم إني أسألك النعيم المقيم الذي لا يحول ولا يزول، اللهم إني أسألك العون يوم العيلة، والأمن يوم الخوف، اللهم إني عائذ بك من شر ما أعطيتنا وشر ما منعتنا، \nاللهم حبب إلينا الإيمان وزينه في قلوبنا، وكره إلينا الكفر والفسوق والعصيان، واجعلنا من الراشدين، \nاللهم توفنا مسلمين وأحيِنا مسلمين، وألحقنا بالصالحين غير خزايا ولا مفتونين، اللهم قاتل الكفرة الذين يكذبون رسلك ، ويصدون عن سبيلك، واجعل عليهم رجزك وعذابك ، اللهم قاتل الكفرة الذين أوتوا الكتاب إله الحق\" \nرسول الله ﷺ بيعلم الصحابة وبيعلمنا من خلال دعائه:\n◇ الشكر الدائم لرب العالمين في كل الظروف، حتى لو بعد ما  تحصل مصيبة لأن حتى مع المصيبة بيكون في خير بس الإنسان ميعرفش، وبيكتشفه بعدين،\nزي مصيبة أُحد، رسول الله ﷺ لسه ميعرفش الأحداث إللي هتحصل لأنه لا يعلم الغيب، لكن هو قدم الشكر لله لأنه عارف إن قدر ربنا كله خير حتى لو كان في ظاهره شر\n◇النظر إلى نعم الله، يعني الإنسان مهما حصل له من المصائب أو الابتلاءات، فربنا أعطى له نِعم أكثر من البلاء،\nفلما يقارن نِعم الله التي لا تُعد ولا تُحصى بالبلاء، يهون البلاء في عين الإنسان\n◇تعظيم الآخرة في عيوننا وعيون الصحابة، يعني مهما ضاقت علينا الدنيا وحصلت لنا مصائب وابتلاءات شديدة لو في المقابل هيكون جزاءنا 《النعيم المُقيم》 إذا صبرنا، \nفأكيد احنا الكسبانين، \nيساوي إيه صبر على البلاء مقابل غمسة واحدة في الجنة تُنسي أبأس أهل الأرض بُؤسه، \nيعني واحد مشفش ساعة حلوة في حياته وهو من أهل الجنة، هيتغمس في الجنة غمسة واحدة بس وهينسى كل تعبه وشقاؤه، أمّال لما يدخلها ويقعد فيها ويأكل من ثمارها ويشرب من أنهارها،\nويقعد في قصورها ويشوف ما لا عين رأت ولا أذن سمعت ولا خطر على قلب بشر ...غمسة واحدة فقط\nالجنة تستاهل إننا نصبر عشانها، نصبر على البلاء...نصبر على الطاعة...نصبر عن المعصية\nرسول الله ﷺ والصحابة تعبانين جسديا ونفسيا، أحداث كثيرة في يوم واحد، فالمفروض إنهم هيريحوا شوية عشان يستعيدوا طاقتهم قبل ما يرجعوا للمدينة لكنهم مغمومين من إللي حصل وكمان كانوا خايفين من إن المشركين يرجعوا ويهجموا عليهم\nفربنا اللطيف بعباده أرسل عليهم النُّعاس، \nعارفين الواحد لما بيكون خايف ومهموم وحاصل معاه مشكلة بيبقى مش عارف ينام ولا عارف يأكل وقلقان\nهو ده كان حال الصحابة في الوقت ده\nلكن ربنا أراد إنه يهون عليهم، وخصوصا إنهم عرفوا الخطأ فين وفعلا صلحوه \nفأول حاجة ربنا عملها معاهم عشان يهوّن عليهم، إنه خلاهم يناموا، لدرجة إن أبا طلحة قال إن سيفه كان كل شوية بيسقط من إيده وهو واقف في الحراسة،\nيعني يغلبه النوم ويسقط السيف وينتبه وبعدين يأخذه، ويغلبه النوم ويسقط السيف وهكذا\nوالنوم دليل على الأمان؛ لأن الإنسان عمره ما هيقدر ينام وفي قلبه خوف\n\"ثُمَّ أَنزَلَ عَلَيْكُم مِّن بَعْدِ الْغَمِّ أَمَنَةً نُّعَاسًا يَغْشَىٰ طَائِفَةً مِّنكُمْ\"\nوده كان لكل إللي في الجيش من المؤمنين،\n لكن كان في طائفة تانية في جيش رسول الله ﷺ صاحيين ومش عارفين يناموا بسبب القلق والتوتر والخوف،\nطائفة مش بتفكر غير في نفسها، طائفة بتظن بالله الظن السيء،\n\"وَطَائِفَةٌ قَدْ أَهَمَّتْهُمْ أَنفُسُهُمْ يَظُنُّونَ بِاللَّهِ غَيْرَ الْحَقِّ ظَنَّ الْجَاهِلِيَّةِ\"\nعشان بس شافوا إن المشركين قتلوا بعض المؤمنين فظهر كأنهم انتصروا عليهم؛ فكّروا إن خلاص كده أمر المسلمين انتهى، وإن المسلمين مش هيبقى لهم وجود تاني، وده كان ظن المشركين كمان،\n\"يَظُنُّونَ بِاللَّهِ غَيْرَ الْحَقِّ ظَنَّ الْجَاهِلِيَّةِ\"\nوقالوا : احنا لم ننتصر زي ما اتوعدنا في بداية المعركة وانهزمنا أهه\n\"يَقُولُونَ هَل لَّنَا مِنَ الْأَمْرِ مِن شَيْءٍ\"\nوإنهم خرجوا للقتال مُكرهين، ولو كان الاختيار بإيدهم مكنوش هيخرجوا ويتعرضوا للقتل\nالطائفة دي هي طائفة المنافقين\n☆إيه ده\nهو مش عبد الله بن أبي بن سلول أخذ المنافقين معاه ورجع المدينة بثلث الجيش من قبل أصلا ما المعركة تبتدي\nعبد الله بن أبي بن سلول رجع فعلا بثلث الجيش وكانوا من المنافقين،\nلكن في ناس من المنافقين شاركوا مع رسول الله ﷺ في غزوة أحد ولم يرجعوا مع عبد الله بن أبي بن سلول ،\nوهو ده إللي بيدل عليه صريح القرآن زي ما شفنا\nربنا بقى رد على كلام المنافقين وبيّنهم لرسول الله ﷺ وللمؤمنين، ودي كانت من أهم نتائج المصيبة إللي حصلت للمؤمنين في أحد...معرفة المنافقين\n\"يُخْفُونَ فِي أَنفُسِهِم مَّا لَا يُبْدُونَ لَكَ \"\nالزبير بن العوام رضي الله عنه بيقول في يوم أحد بعد ما اشتد الخوف عليهم، ربنا أرسل عليهم النوم، فما منّا من رجل إلا وذقنه إلى صدره،\nيعني كلهم ناموا، فالزبير هو كمان غلَبه النوم في اللحظة دي سمع واحد بيقول كلام فحفظه منه ونزل به القرآن بعد كده :\n\"لَوْ كَانَ لَنَا مِنَ الْأَمْرِ شَيْءٌ مَّا قُتِلْنَا هَاهُنَا\"\nالمنافقين قالوا : \n\"يَقُولُونَ هَل لَّنَا مِنَ الْأَمْرِ مِن شَيْءٍ\"\nربنا قال لهم : \"قُلْ إِنَّ الْأَمْرَ كُلَّهُ لِلَّهِ\"\nيعني النصر والشهادة والقضاء والقدر كله بيد الله\nقالوا لو كان الاختيار لنا مكناش هنقتل، رد عليهم القرآن :\nإن محدش بيهرب من قدره، حتى لو انتم في بيوتكم وربنا كتب عليكم القتل، كل واحد هيخرج للمكان إللي مكتوب عليه يُقتل فيه ولن يُنجيهم قعودهم،\n\"قُل لَّوْ كُنتُمْ فِي بُيُوتِكُمْ لَبَرَزَ الَّذِينَ كُتِبَ عَلَيْهِمُ الْقَتْلُ إِلَىٰ مَضَاجِعِهِمْ\"\n☆يعني منقلش مثلا لو فلان مكنش سافر النهاردة مكنش هيعمل حادثة ويموت، لأ...هو ده أجله ونصيبه، ولو مكنش طلع سافر وعمل حادثة، كان هيطلع برده في مكان تاني ويعمل حادثة ويموت ومكنش هينفعه إنه مسافرش ، فهو أَجل وقدر الله \nوختم ربنا الآية بإنه قال لهم :\n\"وَلِيَبْتَلِيَ اللَّهُ مَا فِي صُدُورِكُمْ وَلِيُمَحِّصَ مَا فِي قُلُوبِكُمْ ۗ\"\nيعني أيها المنافقون إللي ربنا عمله يوم أحد ده كان عشان يَكشف ويُظهر للناس المستخبي داخل قلوبكم عشان  يعرفوكم ومينخدعوش بكلامكم بعد كده\nالمنافقين مش هيظهروا غير وقت البلاء والأزمات وإطاعة أوامر الله، كل واحد هيطلع إللي جواه ويبان على حقيقته،\nهو مش ربنا قال :\n\"وَنَبْلُوَ أَخْبَارَكُمْ \"\nتخيلوا لو كانت حياة المسلمين كلها انتصارات بدون أي هزيمة \nكان هيدخل في وسط الصف المسلم الصادق والكاذب\nلكن لما الإسلام يبقى ضعيف نسبيا والدولة الإسلامية مصابة بجراح، \nكل إللي كان بيخفي في قلبه الكفر هيظهره،\nوبعدين بعد ما رسول الله ﷺ يرجع للمدينة، ناس كتير جدا من المنافقين هيجاهروا بنفاقهم وعدائهم للإسلام،\nوالمسلمين هيعرفوهم، بعد ما كانوا بيصلوا معاهم ويصوموا ويتكلموا بالخير،\nعارفين عبد الله بن أبي بن سلول إللي انسحب بثلث الجيش كان بيعمل إيه بعد ما أظهر الإسلام وعاش مع المسلمين في المدينة\nفي كل خطبة جمعة إما قبل ما رسول الله ﷺ يخطب أو بعد ما يخطب كان بيطلع يقول للناس: \nهذا رسول الله اتبعوه والزموا غرسه وانصروه، فاللي كان يشوفه ويسمعه، يقول يا سلام على الإيمان والتقوى\nلأن هو ده الظاهر، وأمثال عبد الله بن أبي بن سلول موجودة في عصرنا كتير،\nيبان لنا إنه حريص على الدعوة ومصلحة الإسلام والمسلمين وهو قلبه لا يعلم به إلا الله\nبعد إللي عبد الله بن أبي بن سلول سلول عمله في غزوة أحد، لما هيرجع رسول الله ﷺ بعدين للمدينة وييجي يخطب وعبد الله بن أبي بن سلول هيقوم ويوعظ الناس زي كل مرة واحد من المسلمين هيشده من ملابسه ويقول له اقعد يا عدو الله \nومن بعدها عبد الله بن أبي بن سلول مش هيطلع تاني يقول الكلام ده؛ لأنه خلاص بقى معروف بالاسم كده إنه منافق\nأيوة غزوة أحد مصيبة لكن في باطنها رحمة وخير، فالمسلمون عرفوا ناس على حقيقتهم مكنوش يتوقعوا أبدا إنهم ضدهم وبيعملوا لمصلحتهم فقط ولا يهمهم مصلحة الإسلام من الأساس\n☆لو تركزوا في الأحداث وتحاولوا تربطوا بينها وبين الواقع بتاعنا في الكم سنة الأخيرة، هتلاحظوا مش هقول لكم التشابه ...لأ.. ده فيه تطابق رهيب بين المواقف والأحداث،\nلكن مين يفهم ويعتبر\nرسول الله ﷺ في الوقت ده كان بيفكر يعمل إيه عشان يطلع المسلمين من الإحباط ومرارة مصيبة أحد،\nفلقى إن أنسب حاجة إنه يطارد جيش مكة، وطبعا ده كان له هدف تاني مهم وهو رسالة لكل أعداء المسلمين، إن المسلمين مازالوا أعزة قادرين على المواجهة برغم الآلام والجراح، وكمان عشان يقطع الطريق على المشركين وميخليهمش يرجعوا يغزوا المدينة\nتاني يوم على طول قال رسول الله ﷺ لبلال بن رباح رضي الله عنه إنه يؤذن في الناس للخروج وراء جيش المشركين،\nومحدش يخرج من المسلمين غير إللي كانوا موجودين في غزوة أحد،\nومفيش واحد يتخلف عن الخروج مهما كانت جراحه\nفكأنه ﷺ  بيقول للصحابة :\nأنا واثق فيكم، وإن الخطأ إللي حصل ده كان مجرد خطأ عابر مش هيتكرر، \nورسول الله ﷺ لم يسمح بإن أي أَحد يتخلف أو ناس تانية تشارك في القتال الجديد عشان محدش يقول احنا انتصرنا عشان فلان جاء معنا، \nأو احنا انتصرنا لأن فلان مجاش معانا،\nوفعلا استجاب المسلمون لأمر رسول الله ﷺ وبدأوا بالخروج لمطاردة المشركين، \nإللي كان رجله مكسورة، وإللي جسمه كله جراح شديدة، لدرجة إن كان في اثنين إخوات أصيبوا بجراح شديدة، ولما سمعوا أمر رسول الله ﷺ بالخروج ومكنش عندهم دابة يركبوها، واحد منهم كان جراحه أقل من جراح أخوه،\nفكان بيشيل أخوه المصاب ده فترة ويخليه يمشي فترة، \nمنظر الجيش صعب، هيقاتلوا إزاي دول\nوفضلوا فعلا ماشيين...ماشيين لحد ما وصلوا لمكان اسمه حمراء الأسد، بيبعد عن المدينة حوالي ثلاثة عشر كيلو\n☆معلش لازم نقف ونتصور الموقف مع بعض\n الصحابة خرجوا مع رسول اللهﷺ وهم أجسامهم مليانة جراح، متخيلين\n طعنات بالسيوف والرماح والسهام حتى رسول الله ﷺ نفسه كان عنده جراح، يعني جراح محتاجة على الأقل خياطة، وحتى بعد الخياطة الواحد بيبقى تعبان ومحتاج للراحة،\nإزاي الناس دي سمعت الكلام كده بمنتهى السهولة ومفيش واحد فيهم اعترض وقال يا رسول الله أنا تعبان مش قادر أمشي،\nولّا مثلا قال له انت عايزنا نخرج معاك يارسول الله خلاص هات لنا حاجة نركبها، هنمشي إزاي بالمنظر ده\nمفيش...ولا واحد في الستمائة إللي كانوا معاه اعترض بكلمة\nتخيلوا بقى لما واحد نَكرة يتكلم بسوء عن الصحابة دول، وهو أصلا غرقاااان في معصية أوامر رسول الله ﷺ\nولّا يقول هم الصحابة أحسن مننا في إيه يعني\nاحنا فعلا منجيش حاجة جنب الصحابة زي ما رسول الله ﷺ قال :\n\"لَا تَسُبُّوا أَصْحَابِي ، لَا تَسُبُّوا أَصْحَابِي ، فَوَالَّذِي نَفْسِي بِيَدِهِ لَوْ أَنَّ أَحَدَكُمْ أَنْفَقَ مِثْلَ أُحُدٍ ذَهَبًا مَا أَدْرَكَ مُدَّ أَحَدِهِمْ وَلَا نَصِيفَهُ\"\nوصل رسول الله ﷺ عند حمراء الأسد وبدأ يستطلع الأخبار، فعرف إن جيش مكة بعيد عنهم في حمراء الأسد بحوالي خمسة وأربعين كيلو ومعسكرين في مكان اسمه الرّوْحَاء، فجلس رسول الله ﷺ ينتظر جيش المشركين إنهم يرجعوا ويحصل بينهم جولة ثانية،\nفي الوقت ده كان جيش المشركين وقف ومكملش لمكة، قالوا احنا لم ننتصر إلا انتصار جزئي\nمحمد وصاحبيه لسه على قيد الحياة، وجيشه لسه موجود في المدينة، فاحنا استفدنا إيه بقى\nاحنا نرجع للمدينة ونغزوها ونحارب المسلمين ونُبيدهم وهم  لسه في حالة ضعف\nوكان ده رأي أبو سفيان، لكن صفوان بن أمية وبعض المشركين معترضين ورأيهم إنهم يكملوا لمكة وخلاص كفاية كده،\nفي اللحظة دي وصل عندهم واحد اسمه مَعبد بن أبي معبد الخُزاعي وكان في الوقت ده مُشرك ، وهو من قبيلة خُزاعة، وقبيلة خُزاعة مسلمهم ومشركهم بيحبوا مصلحة رسول الله ﷺ والمسلمين،\nفلما رأى أبو سفيان معبد، سأله عن جيش رسول الله ﷺ وهو عارف إنه مَرّ على جيش رسول الله ﷺ في الطريق لأنه جاء من ناحيته فقال له معبد:\nمحمد خرج لكم مع أصحابه في جيش مشفتش زيه أبدا\nواجتمع معاه كل الناس إللي كانت تخلّفت عنه يوم أحد،\nوندموا على إللي ضيعوه في حربكم ، ومتغاظين منكم غيظ مشفتش زيه\n☆مع إن جيش المسلمين مش كده خالص\nلكن معبد لما مرّ على جيش رسول الله ﷺ وعرف إللي حصل لأصحابه زعل وقال لرسول الله ﷺ:\nاحنا يعز علينا  إللي حصل لك ،وكنا نحب إن ربنا يعافيك في أصحابك\nفحب معبد إنه يساعد رسول الله ﷺ بأي شيء فقال الكلام ده لأبو سفيان.\nأبو سفيان لما سمع كلام معبد خاف وقال له : انت بتقول إيه\nقال له معبد: انت شكلك مش هتمشي غير لما تشوف جيش محمد داخل عليك بخيله\nفأبو سفيان قال له: \nاحنا كنا اتفقنا إننا هنروح نبيدهم في المدينة\nفمعبد قال له:\nنصيحتي لك، بلاش\nفأُحبط أبو سفيان وانهارت معنويات الجيش المكي ومن خوف أبو سفيان من جيش المسلمين،\nبعث رجل لرسول الله ﷺ عشان يخوفه هو كمان وبالتالي يصرف نظر عن مطاردة جيش مكة ويرجع للمدينة،\nقال لرجل من المشركين: \nاذهب لمحمد وبلغه إننا جمعنا جيش كبير وهنيجي نُبيده هو وأصحابه \n☆حرب معنوية بقى\nفلما وصلت الرسالة لرسول الله ﷺ ولأصحابه قال الصحابة إللي أجسادهم مليانة جراح:\nحسبنا الله ونعم الوكيل\nيعني يكفينا إن ربنا معانا، فسجل لهم القرآن موقفهم وكلامهم:\n\"الَّذِينَ قَالَ لَهُمُ النَّاسُ إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ فَاخْشَوْهُمْ فَزَادَهُمْ إِيمَانًا وَقَالُوا حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ\"\nوإللي بيتوكل على الله، ويصدق في التوكل، ربنا يكفيه، هو البشر دول إيه يا جماعة، هو حد يقدر يرفع إصبع واحد إلا بأمر من ربنا،\nإللي بيكون مع ربنا ويتوكل عليه فعلا، ربنا بينصره وبيصرف عنه كل أذى، وده إللي حصل مع الصحابة،\nهم كانوا مستعدين إنهم يُفنوا حياتهم في الدفاع عن رسول الله ﷺ وعن الدين، \nوعايزين يُظهروا صدقهم وإن إللي حصل في غزوة أحد كان مجرد خطأ عابر، فمحدش فيهم خاف وأصروا جميعا على القتال\nفكانت النتيجة إن ربنا عافاهم وصرف عنهم الأذى ورجع أبو سفيان لمكة، \nوظل المسلمون في مكان حمراء الأسد ثلاثة أيام لحد ما سمع العرب، إن محمد وأصحابه جاءوا وانتظروا جيش مكة، وجيش مكة هو إللي خاف وهرب،\nوانقلبت الهزيمة إلى نصر\n\"فَانقَلَبُوا بِنِعْمَةٍ مِّنَ اللَّهِ وَفَضْلٍ لَّمْ يَمْسَسْهُمْ سُوءٌ وَاتَّبَعُوا رِضْوَانَ اللَّهِ ۗ وَاللَّهُ ذُو فَضْلٍ عَظِيمٍ \"\nأما بقى إللي بيخاف خوف يمعنه عن نصرة الإسلام، ودايما خايف من أعدائه وبيسارع لإرضاء العدو على حساب الدين وخايف من مكائد العدو، فدي صفات المنافقين وضِعاف الإيمان، \nربنا بيقول عنهم:\n\"فَتَرَى الَّذِينَ فِي قُلُوبِهِم مَّرَضٌ يُسَارِعُونَ فِيهِمْ يَقُولُونَ نَخْشَىٰ أَن تُصِيبَنَا دَائِرَةٌ\"\nوالخوف ده من أهم الأسباب إللي وصل أمة الإسلام للحال إللي هي فيه دلوقتي، \nإللي يخاف على رزقه يتنازل عن دينه، وإللي يخاف على حياته يتنازل عن دينه، كل واحد يخاف أول حاجة يفكر يتنازل عنها هي دينه للأسف،\nمع إن ربنا بيقول لنا بكل وضوح :\n\"وَإِن تَصْبِرُوا وَتَتَّقُوا لَا يَضُرُّكُمْ كَيْدُهُمْ شَيْئًا\"\nفلو كان الإنسان صادق في التوكل على الله كان عرف إن الرزق ده من عند الله، وطاعة ربنا لن تمنع أبدا رزق الله،\nوكان عرف إن الأمة لو اجتمعت على أن يضروا المسلم بشيء لن يضروه إلا بشيء قد كتبه الله عليه،\nلو المسلم عمل مثل الصحابة  هينقلب بنعمة من الله وفضل لن يمسه سوء\nبدأ جيش المسلمين يجهز نفسه للعودة إلى المدينة، إزاي هيستقبل أهل المدينة جيش المسلمين، وإيه أهم الأحداث إللي هتحصل بعد كده،\nده إللي هنعرفه الجزء الجاي إن شاء"}, {"n": 104, "l": "الجزء 78 | الشهداء ومنازلهم | رجوع رسول الله صلى الله عليه وسلم الي المدينه", "u": "https://www.facebook.com/groups/710210019782034/permalink/812771836192518/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية_\n#الحلقة_الثامنة_والسبعون\n#الشهداء_ومنازلهم\n#رجوع_رسول_الله_إلى_المدينة\nوقفنا المرة إللي فاتت عند بداية تحرك جيش المسلمين عشان يرجعوا للمدينة بعد غزوة حمراء الأسد،\nاحنا بقى هنسيب جيش المسلمين يرجع للمدينة ونروح لعالم البَرْزخ\n☆ الصحابة إللي قُتلوا في غزوة أحد دول إيه إللي حصل لهم بعد موتهم\nالصحابة الذين قُتلوا في سبيل الله في غزوة أحد هم شهداء ... أحياء عند ربهم يُرزقون في الجنة،\nيعني هم في الدنيا بالنسبة لنا احنا أموات ويجري عليهم أحكام الأموات، يعني لو واحد منهم ترك ميراث، يرثه أهله وزوجته مثلا يتزوجها غيره بعد عدتها، وتُدفن جثته في القبر وهكذا \nأما في القبر فربنا جعلهم أحياء 《بأرواحهم فقط》حياة برزخية غير الحياة إللي احنا عارفينها،\nحياة مختلفة تماما عن حياتنا، مهما حاولنا نتخيلها مش هنعرف لأنها ملهاش شبه ومنعرفش أصلا هي عاملة إزاي\nلكن عندنا بعض الوصف لأرواح الشهداء موجودة فين،\nفي الحديث الصحيح إن أرواح الشهداء في:\n\"جَوْفِ طَيْرٍ خُضْرٍ لَهَا قَنَادِيلُ مُعَلَّقَةٌ بِالْعَرْشِ تَسْرَحُ مِنْ الْجَنَّةِ حَيْثُ شَاءَتْ ثُمَّ تَأْوِي إِلَى تِلْكَ الْقَنَادِيلِ\"\nمعنى الكلام إن:\n◇أرواح الشهداء ربنا جعلها هي نفسها تتشكل على هيئة الطير الخُضر دي وتسرح في الجنة زي ما هي عايزة وتأكل من الجنة، زي ما ربنا بيجعل المَلك يتشكل بصورة بشر\n◇أو إن أرواح الشهداء ربنا جعلها في جسد جديد وهو الطير الخُضْر بدل الجسد إللي أتلفه العدو في المعركة كنوع من العوض أو المكافأة للشهيد، \nبحيث تقدر الروح من خلال الطير ده إنها تروح لأي مكان في الجنة وتأكل منه، كأنها وسيلة نقل يعني\nوبعد كده الطير الخُضر تأوي للقناديل المُعلقة تحت العرش، زي ما الطيور بتأوي لبيوتها على آخر النهار،\nوطبعا القناديل دي مش هي بيوت وقصور الشهداء إللي هيستقروا فيها للأبد\nدي حاجة مؤقتة لحد ما يدخلوا الجنة دخولا كاملا يوم القيامة بالروح والجسد مع بعض، \nوهم يرون قصورهم ومقاعدهم من الجنة، لكن النعيم التام يوم القيامة \nربنا سأل شهداء الصحابة بعد غزوة أحد وهم في جوف الطير الخُضر :\nهل تشتهون شيئا؟ يعني هل نفسكم في شيء؟\nفقالوا :\nهنشتهي إيه أكثر من إننا نسرح في الجنة حيث شئنا \nفسألهم ربنا ثلاثة مرات هل تشتهوا شيء؟\nفلما شافوا إنهم لن يُتركوا غير لما يتمنوا، قالوا:\nيارب رجّع أرواحنا في أجسادنا في الدنيا عشان نُقتل مرة ثانية في سبيلك \nوكلّم الله عبد الله بن حرام إللي كان عنده تسع بنات وهو والد جابر، بدون حجاب، ودي ميزة لم تحصل مع أي أحد غير عبد الله بن حرام، \nفربنا لم يُكلم بشر أبدا إلا من وراء حجاب ما عدا عبد الله بن حرام، وده كان بسبب شدة إيمانه وتقواه وعمله الصالح والمسارعة في الخيرات وجهاده في سبيل الله،\nقال له الله:\nيا عبدي تَمَنّ عليّ أعطيك.\nفقال عبد الله بن حرام:\nأتمنى يارب تُحيِيني فأُقتل فيك مرة ثانية،\nودي حاجة محدش بيتمناها غير الشهيد، يعني الشهيد بعد ما يُقتل ويشوف منزلته وكرامته عند ربنا يتمنى إنه يرجع للدنيا عشان يُقتل في سبيل الله مرة ثانية وثالثة لحد عشر مرات زي ما رسول الله ﷺ قال في الحديث\nلكن ربنا عز وجل قال لهم إنه لن يُرجع إلى الدنيا أي أحد مات\nودي هي القاعدة العامة للبشر، في بعض الحالات إللي بتشذ عن القاعدة، زي إللي اتكلمنا عنهم في قصص الأنبياء\nفاكرين عُزير و الجماعة إللي ربنا قال لهم موتوا ثم أحياهم وغيرها من القصص عن إحياء الموتى،\nدول كان في حكمة من إحيائهم وهي بيان قدرة ربنا على إحياء الموتى، \nلكن القاعدة الأساسية إن محدش هيرجع بعد موته للدنيا\nوالشهداء أقسام،\nفي منهم إللي بيسرح في الجنة حيث شاء زي ما قلنا، وفي قسم في قُبَّةٍ خَضْرَاءَ على نهر بباب الجنة يخرج لهم رزقهم من الجنة الصبح وبالليل،\nوفي احتمال إن أرواح الشهداء بتجتمع عند النهر إللي على باب الجنة ده ويأتيهم رزقهم من الجنة مع بعض\nومش معنى إنهم بياكلوا ويشربوا إن الأكل والشرب مهم لهم عشان يفضلوا عايشين زينا\nيعني احنا بناكل ونشرب عشان نفضل على قيد الحياة صح؟\nهم بقى حياتهم مش محتاجة أكل وشرب عشان يفضلوا عايشين، هم بياكلوا وبيشربوا من الجنة كنوع من أنواع النعيم\nوالشهداء في الجنة مش كلهم في نفس الدرجة ،\nيعني ربنا جعل الجنة درجات، الشهداء لوحدهم لهم في الجنة مائة درجة، \nأعلى درجة للشهيد زي ما رسول الله ﷺ قال:\n\"رَجُلٌ مُؤْمِنٌ قَاتَلَ بِنَفْسِهِ وَمَالِهِ فِي سَبِيلِ اللَّهِ حَتَّى إِذَا لَقِيَ الْعَدُوَّ قَاتَلَهُمْ حَتَّى يُقْتَلَ،\n فَذَلِكَ الشَّهِيدُ الْمُفْتَخِرُ فِي خَيْمَةِ اللَّهِ تَحْتَ عَرْشِهِ ، لا يَفْضُلُهُ النَّبِيُّونَ إِلا بِدَرَجَةِ النُّبُوَّةِ\"\nوسيد الشهداء كلهم حمزة بن عبد المطلب عم رسول الله ﷺ \n☆طيب هو ليه الشهيد اسمه الشهيد \n◇لأن ربنا والملائكة يشهدون له بالجنة.\n◇أو لأنه حي فكأن روحه شاهدة، يعني حاضرة.\n◇أو لأن الأنبياء يشهدون له بحسن الاتباع لهم.\nوغيرها من المعاني إللي العلماء قالوها\nوربنا أعطى الشهيد سبع مزايا\n◇الشهيد ربنا بيغفر له كل ذنوبه في أول دَفعة من دَمه.\n◇بيشوف مقعده من الجنة وهو لسه في الدنيا.\n◇يَأْمن من سؤال الملكين في القبر، يعني لا يُسأل من ربك وما دينك ومن نبيك في القبر زي باقي الناس؛\nلأن السؤال في القبر ربنا جعله لامتحان المؤمن الصادق في إيمانه من المنافق إللي بيدعي الإيمان، \nوثبوت المسلم تحت بَارِقة السيوف أَدَل دليل على صدقه في إيمانه ، وإلا كان هيهرب \n◇ يأمن يوم الفزع الأكبر، إللي هو يوم القيامة وقت ما الناس تقوم من قبورها، الناس هتبقى خايفة إلا الشهيد وكل أهل الإيمان والتقوى.\n◇يُوضع على رأسه تاج الوقار، الياقوتة الواحدة إللي موجودة في التاج، خير من الدنيا وما فيها\nيعني الياقوتة إللي الواحدة إللي بتزين التاج أحسن من كل إللي في الدنيا،\nوده معناه إن كل أموال الدنيا وذهبها وجواهرها مش هتيجي حاجة جنب ياقوتة واحدة في تاج الوقار بتاع الشهيد متخيلين\nأمال التاج نفسه هيكون عامل إزاي بقى\n◇هيشفع عند ربنا في سبعين من أهله، يعني ناس من أهله كانوا هيدخلوا النار فهيشفع فيهم، حتى لو كانوا من أهل الكبائر وربنا رضي إنه يشفع فيهم.\n◇ربنا هيُزوجه اثنتين وسبعين زوجة من الحور العين.\nالشهداء لما شافوا النعيم إللي هم فيه قالوا :\nياريت إخواننا يعرفوا إللي ربنا عمله معانا، عشان محدش يزهد في الجهاد ويرغبوا فيه ومحدش يَجْبُن في الحرب ويتشجعوا\nفقال لهم الله :\nأنا أبلغهم عنكم، فأنزل الله على رسوله ﷺ:\n\"وَلَا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ أَمْوَاتًا ۚ بَلْ أَحْيَاءٌ عِندَ رَبِّهِمْ يُرْزَقُونَ\"\nكل الكلام إللي احنا قلناه عن الشهداء ده \n هو خاص بالشهيد في المعركة، الذي لا يُغسل ولا يُصلى عليه\nأما إللي يتمنى إنه يموت شهيد بصدق ويموت عادي من غير ما يُقتل في سبيل الله، أو من يُقتل بالطاعون أو بالهدم أو بمرض في البطن،\nأو مَن يموت غرقا، أو مَن يُقتل ظُلما، أو من يُقتل وهو بيدافع عن عرضه أو دينه أو ماله، أو يموت بسبب هدم يعني وقع عليه جدار، أو صدمته سيارة أو انقلبت به سيارة،\nفكل هؤلاء يكونوا شهداء، ويكونوا في منازل الشهداء يوم القيامة، لكنهم يُغسلوا ويُكفنوا ويُصلى عليهم،\nلكن زي ما قلنا درجات الشهداء مائة درجة وشفنا مين أعلاها، فالشهداء مش كلهم في درجة واحدة،\nوالسبع ميزات إللي قلنا عليهم هم للشهيد إللي قُتل في سبيل الله في المعركة فقط \nنرجع بقى لرسول الله ﷺ ولجيش المسلمين\nوصل الجيش للمدينة وبدأ الناس يتجمعوا عشان يشوفوا أهلهم ومين مات ومين رجع،\nالأخبار إللي كانت واصلة للمدينة إن رسول الله ﷺ قُتل، وأهل المدينة كانوا في هم وغم وحزن،\nفلما دخل الجيش للمدينة الناس عايزة تطمئن على رسول الله ﷺ، \nفجاءت امرأة من الأنصار من بني دِينار تسأل عن رسول الله ﷺ، فالناس قالت لها إن زوجها وأخوها قُتلا ،\nفقالت لهم: ماذا فعل رسول الله ﷺ،  يعني طمنوني على رسول الله، فقالوا لها : هو بخير،\nفقالت لهم: أَرُونِيهِ أنظر إليه، يعني وروهولي أشوفه،\nفأشاروا لها على مكانه، فلما راحت وشافته قالت:\nكل مصيبة بعدك جَلَل، يعني مادام انت سالم يا رسول الله ولسه عايش، أي حد تاني يموت فمصيبتي فيه صغيرة..بسيطة،\nومش هي بس إللي كانت مشاعرها كده، ده أم سعد بن معاذ جاءت لرسول الله ﷺ وكان ابنها عمرو بن معاذ قُتل في أحد،\nفقال سعد لرسول الله ﷺ : أمي يا رسول الله\nفقال رسول الله ﷺ:\nأهلا بها، فلما قربت من رسول الله ﷺ وقعدت تتأمل فيه، قالت له:\nأمَا إذ رأَيْتُك سالما، فقد هانت المصيبة.\n يعني هي بالنسبة لها وجود رسول الله ﷺ سالم في الدنيا أهم عندها من نجاة ابنها، مصيبتها بموت ابنها بسيطة، في مقابل إن رسول الله ﷺ يكون على قيد الحياة،\n♡رسول الله ﷺ هو أهم حاجة في حياة الصحابة رجالا ونساءا، حبهم له ميتوصفش،\nحب الصحابة لرسول الله ﷺ كان أتم من حب غيرهم لأنهم عرفوه كويس والمحبة ثمرة المعرفة،\nيعني الحب الصادق بيكون بعد ما نعرف الإنسان كويس ونعاشره، فالصحابة عرفوا رسول الله ﷺ حق المعرفة،\nفكانت النتيجة هي الحب الشديد له\n\"لا يؤمن أحدكم حتى أكون أحبَّ إليهِ من والده وولده والناس أجمعين\"\nفاللي عايز يحب رسول الله ﷺ بصدق زي الصحابة، لازم يعرف رسول الله ﷺ كويس جدا، ويقرأ ويسمع عن حياته مرة واثنين وثلاثة،\n ويتبع أوامره ويعمل زيه في كل حاجة، وتلقائي هيلاقي في قلبه حبه ﷺ \nعزّى رسول الله ﷺ أم سعد بن معاذ في موت ابنها عمرو، وقال لها :\nأبشرِي وبشِّري الناس إن قتلاهم رفقاء مع بعض في الجنة، وهيشفعوا في أهلهم\nفقالت أم سعد بن معاذ:\nرضينا يا رسول الله، وهو مين يبكي عليهم بعد كده؟\nوقالت له:\nادع يا رسول الله لمن خُلّفوا، يعني بتطلب من رسول الله ﷺ إنه يدعي لأهل الشهداء ،فقال رسول الله ﷺ :\nاللهم أَذهب حُزن قلوبهم، واجبر مصيبتهم، وأحسن الخَلَف على من خلّفوا \nفي كل بيت في المدينة تقريبا كان فيه شهيد، فالنساء قعدت تبكي، ودي حاجة طبيعية يا جماعة\nحتى مع اليقين إنهم في مكان أفضل بكثير من الدنيا، لكن ألم الفراق والحزن والبكاء من طبيعة البشر،\nفكان من الطبيعي إنهم يبكوا على فقد أحبابهم حتى رسول الله ﷺ كان بيبكي لما يتألم ألم نفسي\nلكن إللي تقعد تصوّت وتشق هدومها وتلطم \n وتضرب على رأسها\n أو على صدرها وتقعد تَصيح وتقول كلام فيه اعتراض على قدر الله وقضائه، وقت ما تحصل مصيبة ،هنا بقى الحرام ومن أفعال الجاهلية \nقال رسول الله ﷺ : \"‎ليس منّا من ضرب الخدود أو شقّ الجيوب أو دعا بدعوى الجاهلية‎\"\nالصح بقى إن لما تحصل مصيبة نقول:\nإنا لله وإنا إليه راجعون، قدر الله وما شاء فعل، اللهم آجِرني أوِ أْجُرني في مصيبتي، وأخلف لي خيرًا منها.\nوإللي هيقول الدعاء ده\n ربنا هيُآجره أو يَأْجره في مصيبته، ويخلف له خيرًا منها زي ما رسول الله ﷺ قال\nاليهود والمنافقين\nيتهدوا ويسكتوا ويراعوا دماء المسلمين إللي قُتلوا ولّا يراعوا مشاعر النساء إللي عمالة تبكي وقلبها موجوع على قتلاهم وتمثيل المشركين بجثثهم\nأبدا\nدول ولعوا الدنيا أكثر، وقعدوا يفرقوا بين رسول الله ﷺ وبين المسلمين، ويُحزّنوا المسلمين أكثر،\nوعلى فكرة لو كان عندهم تسجيل وتليفزيون مش بعيد كانوا شغلوا لهم الأغاني إياها\nوقعدوا يقولوا:\nماهو لو كان محمد نبي مكنش الكفار هزموه وانتصروا عليه ولا كان اتصاب منهم الإصابة دي\nلكنه عايز مُلك \nوطالب المُلك مرة الدنيا تكون له ومرة عليه\nعارفين الحَلة لما بنحط فيها مية على النار وتغلي وتقعد تفور\nأهه ده كان المدينة بالضبط، كانت بتفور زي فوران المية إللي بتغلي\nالمسلمين مجروحين...واليهود شمتانين في المسلمين، والمنافقين عمالين يقطّموا في المسلمين:\nلو كنتم سمعتم كلامنا ورجعتم معانا المدينة مكنش حصل إللي حصل، ومكنش حد مات، انتم تتحملوا دمهم بقى عشان مسمعتوش كلامنا\nفنزل القرآن يشرح كل حاجة من البداية في سورة آل عمران، من أول ما رسول الله ﷺ بدأ يجهز الجيش:\n\"وَإِذْ غَدَوْتَ مِنْ أَهْلِكَ تُبَوِّئُ الْمُؤْمِنِينَ مَقَاعِدَ لِلْقِتَالِ ۗ وَاللَّهُ سَمِيعٌ عَلِيمٌ \"\nلحد وصف أحوال الشهداء في الجنة:\n\"وَلَا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ أَمْوَاتًا ۚ بَلْ أَحْيَاءٌ عِندَ رَبِّهِمْ يُرْزَقُونَ\" \nوموقفهم البطولي في غزوة حمراء الأسد،\nوفضح المنافقين، وعزّى المسلمين، وبيّن طاعة من أطاع وعِصيان من عصى والسبب في الهزيمة زي ما شرحنا في الأجزاي إللي فاتت،\nأصل لحد دلوقتي مكنش القرآن لسه نزل ولا كان المسلمين يعرفوا بالضبط إللي حصل، ولا كانوا يعرفوا سبب ترك الرماة للجبل\nكل حاجة وضحت بعد ما رجع المسلمون للمدينة ونزلت الآيات في سورة آل عمران \nحاولوا كده تقرأوا في سورة آل عمران عن غزوة أحد بعد ما عرفتم الأحداث هتحسوا إنكم بتقرأوا الآيات لأول مرة بعد ما فهمتم المعنى\nالمسلمين اتعلموا الدرس، اتعلموا :\n♡إن الابتلاء بيُنقّي الصفوف، ويُظهر العدو المخادع من الصديق الوفي.\n♡إن معصية الله ورسوله هي سبب كل المصائب إللي ممكن تحصل في الدنيا.\n♡إن لو بعض المسلمين بس هو إللي أخطأ فنتيجة الخطأ هتعُم على كل المسلمين ومفيش مُحاباة لأي أحد حتى لو كان رسول الله ﷺ \n♡إنهم لازم يَحذروا من الدنيا ويزهدوا فيها، لأنها لو دخلت قلوبهم وبقت هي همهم فهتكون سبب في ضياع دينهم.\n♡إن رسول الله ﷺ وإن كان أُرسل لكل الدنيا ولكل الناس على مر الزمان ورسالته هي الرسالة الخاتمة، فهو بشر وهيموت، ومش معنى موته إنكم تقفوا وإن الرسالة خلاص انتهت، \nإنتم إللي هتكملوا الرسالة من بعده..إنتم إللي هتوصلوا رسالته لكل مكان في الأرض ولكل الناس على مر الزمن\n\"وَمَا مُحَمَّدٌ إِلا رَسُولٌ قَدْ خَلَتْ مِنْ قَبْلِهِ الرُّسُلُ أَفَإِنْ مَاتَ أَوْ قُتِلَ انْقَلَبْتُمْ عَلَى أَعْقَابِكُمْ وَمَنْ يَنْقَلِبْ عَلَى عَقِبَيْهِ فَلَنْ يَضُرَّ اللَّهَ شَيْئًا\"\nربنا في القرآن مش بس شرح لهم إللي حصل لكن ده كمان وَاسَاهم وخَفف عنهم المصيبة عشان يرفع من روحهم المعنوية عشان يقدروا يكملوا المشوار،\nهي إيه الفايدة لما الواحد يقعد يلوم نفسه ويبكي على اللبن المسكوب زي ما بنقول من غير ما ياخد خطوات إيجابية للتغيير\nربنا قال لهم :\n\"وَلا تَهِنُوا وَلا تَحْزَنُوا وَأَنْتُمُ الأَعْلَوْنَ إِنْ كُنْتُمْ مُؤْمِنِينَ \"\nأيوة حصل منكم خطأ... أيوة المشركين قتلوا أصحابكم،\nأيوة يظهر إن المشركين لهم الغلبة عليكم، لكن انتم الأعلى بعقيدتكم\n \nمهما كانت الدول الغير مسلمة تعلو دول المسلمين بتقدمهم وتقهرهم وتؤذيهم فكل ده مؤقت، \nالمسلمين عندهم إمكانات كبيرة جدا بس محتاجين يستغلوها صح، وأهم الإمكانات دي هي الإيمان بالله ورسوله،\nدي القيمة الوحيدة إللي ترفع المسلم فوق أي إنسان على وجه الأرض\nواحنا شوفنا إزاي الصحابة هزموا المشركين في غزوة بدر وفي بداية غزوة أُحد ولما حصل معصية رسول الله ﷺ الحال اتغير،\nوالصحابة لما فهموا المعنى ده كويس، انتصروا وسادوا الدنيا في سنوات قليلة، مع إن أعدادهم قليلة وإمكاناتهم بسيطة في مقابل أعدائهم،\nلكن إللي يميز المسلمون ويجعلهم أعزة هو طاعتهم لله ولرسوله\nوده إللي ربنا علمه للصحابة والصحابة فهموه وطبقوه، والدور علينا احنا نفهم ونطبق المعنى ده،\n\"وأَنْتُمُ الأَعْلَوْنَ.... إِنْ كُنْتُمْ مُؤْمِنِينَ\"\nوقت ما المسلمين يحققوا الإيمان الكامل بالله ورسوله هيكونوا هم الأعلى في كل الأرض \nوده وعد ربنا للصحابة ولنا، \n\"إِنْ يَنْصُرْكُمُ اللَّهُ فَلا غَالِبَ لَكُمْ\"\nربنا هو الناصر واحنا عارفين القاعدة إللي قلنا عليها قبل كده من بداية السيرة وقلت إنها هتفضل معانا طول السيرة:\n《إن تنصروا الله ينصركم》\nهتنصروا ربنا بإقامة شرعه وبطاعة أوامره وأوامر رسوله هينصركم ومحدش هيقدر يغلبكم أبدا\n\"إِنْ يَنْصُرْكُمُ اللَّهُ فَلا غَالِبَ لَكُمْ\"\nوده حَدَث متكرر يا جماعة... سنة كونية حتى من قبل زمن رسول الله ﷺ، وربنا قال للصحابة كده عشان يربيهم،\nشوفوا الآية بتقول إيه:\n\"وَكَأَيِّنْ مِنْ نَبِيٍّ قاتَلَ مَعَهُ رِبِّيُّونَ كَثِيرٌ فَما وَهَنُوا لِما أَصابَهُمْ فِي سَبِيلِ اللَّهِ وَما ضَعُفُوا وَمَا اسْتَكانُوا وَاللَّهُ يُحِبُّ الصَّابِرِينَ\"\nبيقول لهم انتم مش أول ناس يحصل معاهم كده،\nالسابقين إللي مروا بنفس الموقف بتاعكم ده محدش منهم ضِعف، والقيام بعد السقوط والضعف مش حاجة نادرة بالعكس ده هو القاعدة الصحيحة،\nالقاعدة إن الإنسان مهما فشل أو حصلت له مشكلة يقوم مرة ثانية \n☆والقاعدة دي نستفيد منها حاجة مهمة جدا في حياتنا اليومية، وهي إننا مهما وقعنا في الذنب أو فشلنا في أي شيء نقوم ونحاول مرة ثانية وثالثة ورابعة لحد ما ننجح،\nنفسك يبقى عندك يقين بالله جاهد نفسك وخذ بالأسباب واتعلم لحد ما توصل لدرجة اليقين،\nحاولت مرة وملقتش نتيجة... متيأسش\n قوم وحاول لحد ما توصل لهدفك، انت مش حالة نادرة، كل الناس إللي قبلنا مرّوا بنفس إللي احنا بنمُر بيه دلوقتي،\nبس احنا محتاجين نعرف نقوم صح ونستفيد من أخطائنا عشان نصلح ونبدأ من جديد ونوصل لهدفنا زي ما الصحابة ما عملوا \nإن شاء الله الجزء الجاي هنعرف أهم الأحداث إللي حصلت مع رسول الله ﷺ والصحابة بعد غزوة أحد"}, {"n": 105, "l": "الجزء 79 | الشوري قصة تحريم الخمر", "u": "https://www.facebook.com/groups/710210019782034/permalink/812773316192370/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية_إيمان_\n#الحلقة_التاسعة_والسبعون\n#الشورى\n#قصة_تحريم_الخمر\nاتكلمنا المرة إللي فاتت عن رجوع جيش المسلمين للمدينة بعد غزوة أُحد وشوفنا رد فعل أهل المدينة من المؤمنين ومن المنافقين واليهود كان عامل إزاي،\nوشوفنا تعليق القرآن على أحداث غزوة أحد وفَضْحه للمنافقين،\nوهنا يظهر عندنا نقطة مهمة جدا\nلو رجعنا بالأحداث لقبل غزوة أُحد لما كان رسول الله ﷺ بيشاور الصحابة نطلع نقاتل المشركين خارج المدينة ولّا نقاتلهم داخل المدينة،\nلو فكرنا بالعقل هنلاقي إن الرأي الصحيح كان إن المسلمين يقاتلوا المشركين داخل المدينة زي ما رسول الله ﷺ قال في البداية،\nولكنه خالف رأيه ونزل على رأي الصحابة لأن رأيهم كان الأغلب وطبعا دي كانت أراء اجتهادية منزلش بها وحي قاطع \nيعني من الآخر كده الشورى كانت سبب من أسباب الهزيمة من البداية خالص، والمفروض كان رسول الله ﷺ خلى رأيه هو إللي يمشي وكان يُلزم به المسلمين،\nفبعد ما شفنا الأثر السلبي للشورى في الموقف ده الطبيعي بالعقل إننا نلغي الشورى\nلكن ربنا سبحانه وتعالى قال لرسول الله ﷺ إنه يستمر في مشاورة أصحابه والأخذ برأيهم\nمش معنى إن رأي الشورى كان خطأ مرة يبقى الشورى نفسها سيئة على طول الخط بالعكس،\nده استشارة 《أصحاب الرأي السديد الموثوق فيهم》 \nبتخلق أفكار كثيرة وبتُنتج أراء صحيحة، والمُشاوِر لا يكاد يُخطئ وحتى لو أخطأ فمش هيبقى عليه اللوم زي واحد لم يشاور أحد من البداية\nوكمان من أهم الصفات إللي تخلي القائد محبوب بين جنوده وإنهم يطيعوا أوامره هي المشاورة،\nلأنه لما ياخد رأيهم في الأمور الخاصة بالدولة إللي محتاجة مشورة؛ ده هيخلي الجنود يشعروا إنهم جزء من الدولة دي وإن قائدهم حريص على المصلحة العامة للجميع وهيثقوا فيه،\nوبالتالي هيكونوا حريصين جدا على طاعته وهيبذلوا جهدهم وطاقتهم في مساعدته \nبعكس لو القائد كان مستبد برأيه، وبيتعامل مع الجنود على إنهم مجرد أدوات يجب عليهم تنفيذ الأمر وبس\nهنلاقيهم بيبعدوا عن القائد وكارهينه وحتى لو أطاعوا أمره فهيطيعوه وهم مضطرين ومن غير ما يكون في حرص منهم على مصلحة دولتهم أو حتى دينهم،\nوده إللي ربنا قاله لرسوله ﷺ في القرآن:\n\"فَبِمَا رَحْمَةٍ مِّنَ اللَّهِ لِنتَ لَهُمْ ۖ وَلَوْ كُنتَ فَظًّا غَلِيظَ الْقَلْبِ لَانفَضُّوا مِنْ حَوْلِكَ ۖ فَاعْفُ عَنْهُمْ وَاسْتَغْفِرْ لَهُمْ وَشَاوِرْهُمْ فِي الْأَمْرِ\"\nربنا قال لرسول الله ﷺ إنه يعفو عن الخطأ إللي حصل في غزوة أحد، وبيأمره إنه يستمر في مشاورة أصحابه،\nوإنه لو كان سيء الخُلق وقاسي القلب معاهم كان زمانهم انفضوا من حوله\n☆طيب خلونا نستفيد في حياتنا العملية من قصة الشورى دي، ماهو احنا مش مجرد بنحكي قصة وخلاص احنا عايزين نتربى على أخلاق رسول الله ﷺ وأخلاق القرآن\nالمشاورة مش بتكون بس بين القائد وجنوده،\nالمشاورة بتكون بين الرجل وزوجته، بين الأم والأب وأبنائهم،\nبين الأصحاب وبعض، \nمينفعش الزوج ياخد قرار خاص بالأسرة كلها وهيأثر على أهل بيته كلهم من غير ما ياخد رأيهم ويشاورهم،\nمينفعش الأم مثلا تاخد قرار خاص بأبنائها من غير ما تاخد رأيهم،\n《طبعا في الحاجات إللي محتاجة مشورة فقط \n》\n¤ممكن حد يقول طيب ماهم عقلهم ميستوعبش أو تفكيرهم بسيط لا يرقى لمستوى تفكيري = الزوجة أو  الأبناء مثلا=  \nحلو أوي\nاحنا متفقين إن رسول الله ﷺ هو أكمل الناس وأفضلهم رأيا وعقلا وأكثرهم علما،\nربنا بقى أمر أكمل الناس وأفضلهم رأيا وعقلا وأكثرهم علما إنه يشاور مَن هُم أقل منه في العقل والحكمة والرأي والعلم،\nفمن باب أَوْلى إن إللي أقل من رسول الله ﷺ محتاج يشاور ويشوف آراء إللي حواليه\nوعلى فكرة هي دائرة \nالزوجة إللي مش بتشاور أبنائها وبتأخذ برأيهم وعلى طول مستبدة برأيها، هتلاقي ربنا مسلط عليها زوج مستبد مش بياخد برأيها ولا بيشاورها في حاجة،\nوالزوج إللي مُستبد برأيه ومش بيشاور زوجته وعياله هتلاقي ربنا مسلط عليه مدير قارفه في الشغل مثلا\n◇《طبعا أنا بتكلم في القاعدة العامة، مش بنقيس على شواذ القاعدة ، يعني ممكن تكون واحدة مثلا بتشاور أبنائها وربنا مسلط عليها زوج مُستبد كنوع من أنواع الابتلاء، دي حاجة تانية مش موضوعنا خالص\n》\nفقاعدة الشورى من صفات الجيش إللي ربنا بينصره، وكذلك قاعدة الشورى 《صفة》 من صفات الأسرة المستقرة نفسيا\nمن الحاجات إللي ربنا علمها للصحابة في القرآن هو الاستغفار لما يقابلوا العدو،\nخلونا نشوف الآيات، ربنا بيقول:\n\"وَكَأَيِّن مِّن نَّبِيٍّ قَاتَلَ مَعَهُ رِبِّيُّونَ كَثِيرٌ فَمَا وَهَنُوا لِمَا أَصَابَهُمْ فِي سَبِيلِ اللَّهِ وَمَا ضَعُفُوا وَمَا اسْتَكَانُوا ۗ وَاللَّهُ يُحِبُّ الصَّابِرِينَ\"\nيعني كم من نبي قاتل معه ربانيون =ناس صالحين= كثير ومحدش فيهم ضِعف ولا استكان لما نبيهم اتقتل،\n بالعكس ده  استمروا في القتال على منهج نبيهم ودافعوا عن دين الله\nفكان الأَوْلى إنكم تعملوا زي أتباع الأنبياء السابقين،\nمش إنكم تضعفوا وتقفوا عن القتال لمجرد إنكم سمعتم واحد بيصيح إن محمد رسول الله ﷺ قُتل\nوفي الآية إللي بعدها ربنا علمهم إيه إللي عملوه أتباع النبي  لما نبيهم قُتل فعلا ومكنش إشاعة قال:\n\"وَمَا كَانَ قَوْلَهُمْ إِلَّا أَن قَالُوا رَبَّنَا اغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِي أَمْرِنَا وَثَبِّتْ أَقْدَامَنَا وَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ\"\nالمُتوقع إنهم يدعوا بالنصر يعني يقولوا يارب انصرنا على طول، لكنهم أول ما بدأوا في الدعاء دعوا إن ربنا يغفر لهم ذنوبهم الصغيرة ويغفر لهم الكبائر، \nوبعدين دعوا بالثبات والنصرة على الكافرين\n☆طب ليه\nشوفوا،\nأساسيات الدين عند ربنا واحدة من أول آدم عليه السلام لحد محمد ﷺ، لكن التشريعات إللي هي الحلال والحرام هي إللي بتختلف من أمة لأمة تانية،\nفالأساسيات زي خطر الذنوب والمعاصي وإنها سبب لهلاك الأمم موجودة مع كل الأنبياء وحذّروا منها قومهم،\nواحنا شفنا في قصص الأنبياء هلاك الأمم بسبب ذنوبهم،\nوربنا نفسه قال لنا في القرآن عن أمم سابقة إنه أهلكها بسبب ذنوبها:\n\" فَأَهْلَكْنَاهُم بِذُنُوبِهِمْ \"\nفهنا أتباع النبي ده إللي احنا منعرفش اسمه، كانوا عارفين خطر الذنوب والمعاصي وإنها سبب رئيسي في كل مصيبة تحصل،\nفكان طبيعي إن أول حاجة يعملوها إنهم يستغفروا من ذنوبهم الأول إللي هي سبب الهزيمة،\nلأن ربنا لو غفر لهم ذنوبهم هيرفع عنهم البلاء والهزيمة وهينصرهم\nواحنا شفنا في غزوة أُحد إن سبب الهزيمة كان معصية أمر رسول الله ﷺ،\nفبيعلمهم إن حتى لو حصل منكم معصية صغيرة أو حتى كبيرة من الكبائر فلازم تتوبوا وتستغفروا، ومحدش يستهون بمعصية أو يشوف إنها حاجة بسيطة يعني ومش هي دي إللي هتعمل أزمة\nلأن الذنوب سبب رئيسي في الخذلان في موقف النصر،\nتعالوا نشوف القرآن بيقول إيه:\n\"إِنَّ الَّذِينَ تَوَلَّوْا مِنكُمْ يَوْمَ الْتَقَى الْجَمْعَانِ إِنَّمَا اسْتَزَلَّهُمُ الشَّيْطَانُ بِبَعْضِ مَا كَسَبُوا\"\nيعني الناس إللي هربت من المعركة دي هروبهم كان بسبب ذنوب لهم قديمة لم يتوبوا منها\n☆خلونا نربط الكلام ده بالواقع بتاعنا\n لما مثلا واحد ينام عن صلاة الفجر وتروح عليه الصلاة،\nهو مش عارف إن سبب حرمانه من صلاة الفجر كان النظرة إللي نظرها لحرام، سواء مقطع فيديو فيه حرام أو نظرة لبنت في الشارع أو...أو...\nأو مثلا البنت إللي مش عارفة تحفظ القرآن وعمالة تشتكي وللأسف مش عارفة إن سبب حرمانها من الحفظ هي الغيبة إللي واقعة فيها ليل نهار ومش بتتوب منها،\nتخيلوا بقى لما تجتمع الغيبة مع النظر للحرام مع سماع الأغاني مع رؤية المسلسلات والأفلام مع الذهاب للمصايف المختلطة وعدم إنكار المنكر مع....مع...النتيجة هتكون إيه\nكل عمل خير بنتحرم منه بيكون بسبب ذنب حصل واحنا متبناش منه، والأخطر إن الإنسان ساعات بينتكس بسبب ذنوبه إللي متبش منها\nشوفوا  عبدُ اللهِ بنُ مسعودٍ الصحابي بيقول إيه : \nإنَّ المؤمنَ يرَى ذنوبَه كأنه في أصلِ جبلٍ يخافُ أنْ يقعَ عليه وإنَّ الفاجرَ يرَى ذنوبَه كذبابٍ وقع على أنفِه قال به هكذا ، فطَار. \nيعني《 المؤمن 》على طول شايف ذنوبه زي الجبل وهو تحت الجبل ده، في أي لحظة الجبل ممكن يقع عليه فخايف منه،\nتخيلوا نفسكم ماشيين جنب عمارة آيلة للسقوط وفي تحذير : يا جماعة كله يبعد عن العمارة دي عشان ممكن تقع في أي لحظة، هل ممكن حد يقرب منها ولّا كله هيبعد عنها عشان خايف من العمارة تقع عليه\nهل بقى ممكن حد يروح يسكن في العمارة إللي باين عليها إنها ممكن تقع في أي لحظة؟\nطبعا لأ\nكذلك المؤمن على طول خايف من ذنوبه وشايفها حاجة كبيرة جدا وخايف إنها ممكن تكون سبب في هلاكه \n《الفاجر》بقى مش بتفرق معاه ذنوبه، بيشوف ذنوبه كأنها ذبابة جاءت وقفت على أنفه فهشها بإيده،\nيعني هو شايف ذنوبه دي حاجة بسيطة جدا ،ومستهين بها ومش فارق معاه حاجة\nوخوف الإنسان من ذنوبه بيخليه يشوف نفسه على طول مقصر في حق الله ويدفعه إنه يجتهد أكثر في طاعة ربنا وهو ده المطلوب\nوطبعا إللي بيخاف من ذنوبه إنها تُهلكه بيكون خايف من ربنا وإللي بيخاف من ربنا في الدنيا ربنا بشّره بالأمان في الآخرة\nربنا بيقول في حديث قدسي:\n\"وعزتي لا أجمع على عبدي خوفَيْن ولا أجمع له أمْنيْن ، إذا أَمِنَني في الدنيا أَخَفْته يوم القيامة ، وإذا خافني في الدنيا أَمّنته يوم القيامة \"\nوربنا قال في القرآن:\n\"وَلِمَنْ خَافَ مَقَامَ رَبِّهِ جَنَّتَانِ \"\nيعني الإنسان إللي بيخاف ربنا \n《الخوف إللي يمنعه عن معصية ربنا ويدفعه إلى طاعته 》\nربنا هيكافئه بجنتين، ببساتين يعني كل إللي فيها من ذهب \nمش الخوف إللي يوصل للقنوط واليأس من رحمة ربنا ولا الخوف إللي يمنعنا من عمل الصالحات\nوالصحابة يا جماعة كانوا زينا مليانين عيوب وكانوا بيقعوا في الذنوب وحتى في الكبائر\nواحنا شفنا حالهم قبل الإسلام كان عامل إزاي،\nلكن هم لما سلموا أنفسهم للإسلام والإسلام رباهم فبقوا حاجة تانية خالص\nواحنا برده لو ربينا نفسنا بالإسلام زيهم هنبقى حاجة تانية خالص، يعني هم مكنش عندهم حاجة مش عندنا،\nكان عندهم قرآن وسنة واحنا كمان عندنا قرآن وسنة، فاضل بس إننا نتعلم ونطبق إللي بنتعلمه زيهم واحنا حالنا هيختلف،\nتخيلوا لو كل واحد فينا بدأ بنفسه يعلمها أخلاق الإسلام ويصبر على تربية نفسه أكيد حال أمة الإسلام هيتخلف،\nلكن أهم حاجة إننا منستعجلش النتيجة، ونفتكر دائما إن رسول الله ﷺ قعد يربي الصحابة من خلال القرآن ثلاثة وعشرين سنة،\nثلاثة عشرة سنة في مكة وعشر سنين في المدينة، فما بالكم بقى بغيرهم محتاجين كم سنة \nوزي ما قال يوسف عليه السلام :\n\"إِنَّهُ مَن يَتَّقِ وَيَصْبِرْ فَإِنَّ اللَّهَ لَا يُضِيعُ أَجْرَ الْمُحْسِنِينَ\"\nفاكرين القاعدة إللي قلناها في قصة يوسف عليه السلام\nتقوى(الخوف من الله)+ صبر =فرج من الله وفتح مبين \n♡طبعا غزوة أحد فيها عِبر ودروس كثيرة جدا، وأنا قلت خطوط عريضة بس، فاللي عايز يستفيض ويعرف أكثر ممكن يراجع غزوة أحد للدكتور راغب السرجاني،\nوكمان غزوة أحد للشيخ حازم صلاح أبو إسماعيل أربع أجزاء، وسلسلة غزوة أُحد للشيخ أبو إسحاق الحويني،\nبعد غزوة أُحد بفترة وفي خلال السنة الثالثة للهجرة، ربنا أنزل على المسلمين من الصحابة حكم جديد من أحكام الإسلام والحكم ده هو تحريم الخَمْر\n《وأشهر الأقوال عند العلماء إن الخمر حُرّمت بعد غزوة أحد 》\nتعالوا نشوف قصة الخمر مع العرب من البداية كانت إيه\nالعرب قبل الإسلام كان بيشربوا الخمر زي المية كده، وكان شعراء كثير في العصر الجاهلي بيبدأوا الشعر بتاعهم بمدح الخمر والكلام عنه،\nوكانت الخمّارات وجلسات الشّرب منتشرة بين العرب في الجاهلية، وكانوا بيستوردوا الخمر من خارج أرض الجزيرة العربية،\nوكانوا بيتفاخروا بامتلاكهم للخمر وبيعتبروه علامة على غنى الشخص، فكان شرب الخمر جزء من حياة العرب في الجاهلية،\nوكان في بعض الأشخاص حرّموا الخمر على أنفسهم لأنهم شافوا أثاروا السلبية وإزاي إنه بيُذهب العقل والإنسان مش بيكون في وعيه وممكن تحصل له مصائب كبيرة\nوكان من الناس إللي حرمت الخمر على نفسها أبو بكر الصديق رضي الله عنه وعثمان بن عفان ومحمد رسول الله ﷺ وكان كل ده قبل الإسلام،\nبعد ما جاء الإسلام خلال الثلاثة عشرة سنة الأولى من البعثة كان الكلام كله عن توحيد الله بالعبادة وعن الجنة والنار وقصص الأنبياء السابقين،\nلما رسول الله ﷺ هاجر للمدينة وكانوا بيشربوا الخمر وبيأكلوا الميسِر، إللي هو القمار يعني،\nسألوا رسول الله ﷺ عن الخمر وعن الميسِر، يعني حاجة حلوة ولا حاجة وحشة بما إنها أمور منتشرة بينهم،\nفأنزل الله تعالى في القرآن:\n\"يَسْأَلُونَكَ عَنِ الْخَمْرِ وَالْمَيْسِرِ ۖ قُلْ فِيهِمَا إِثْمٌ كَبِيرٌ وَمَنَافِعُ لِلنَّاسِ وَإِثْمُهُمَا أَكْبَرُ مِن نَّفْعِهِمَا\"\nفالناس قالوا :\nربنا محرمهاش، قال بس إن فيها إثم كبير\nفاستمروا يشربوا الخمر عادي، لحد ما في يوم من الأيام واحد من المهاجرين كان بيصلي بأصحابه إمام في صلاة المغرب فخَلَط في القراءة، يعني أدخل الآيات في بعضها،\nفأنزل الله آية أشد من الآية السابقة:\n\"يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَقْرَبُوا الصَّلَاةَ وَأَنْتُمْ سُكَارَىٰ حَتَّىٰ تَعْلَمُوا مَا تَقُولُونَ\"\nواستمر الناس في شرب الخمر لكن طبعا مش زي الأول عشان يكونوا فايقين في الصلوات الخمس،\nلأن كان عندهم الصلوات الخمس دي حاجة مُقدسة، محدش كان بيتخلف عن صلاة الفريضة في المسجد\nوكان عمر بن الخطاب رضي الله عنه بيدعي ربنا:\nاللهم بيّن لنا في الخمر بيانا شافياً، يعني يارب عايزين الخلاصة في موضوع الخمر ده،\nوكان رسول الله ﷺ بيقول للناس في خطبة خطبها في المدينة إن ربنا بيتكلم عن الخمر، وهو يظن أن الله تعالى هينزل فيها أمر، فأي حد عنده شيء من الخمر فليبعها وينتفع بها\nوفعلا بعد فترة بسيطة نزلت آيات تحريم الخمر:\n\" يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالْأَنصَابُ وَالْأَزْلَامُ رِجْسٌ مِّنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ۩ \nإِنَّمَا يُرِيدُ الشَّيْطَانُ أَن يُوقِعَ بَيْنَكُمُ الْعَدَاوَةَ وَالْبَغْضَاءَ فِي الْخَمْرِ وَالْمَيْسِرِ وَيَصُدَّكُمْ عَن ذِكْرِ اللَّهِ وَعَنِ الصَّلَاةِ ۖ فَهَلْ أَنتُم مُّنتَهُونَ\"\nلما وصلت الآية لعمر بن الخطاب رضي الله عنه قال :\nانتهينا\nوقال رسول الله ﷺ للناس :\nربنا حرم الخمر، فأي واحد توصله الآية وعنده شيء من الخمر فلا يشرب ولا يبِع منها شيء، وأي حد عنده شيء من الخمر يأتيني به،\nفكل إللي كان عنده شيء من الخمر في زِقٍّ أو راوية جاء بها، حاجات كده زي زجاجات المياه عندنا\nوقف رسول الله ﷺ وسط الناس وقال لهم :\nعارفين إيه دي؟\nفالناس قالوا له : دي خمر\nفقال لهم رسول الله ﷺ:\n صدقتم\nفإن الله لعن :\nالخمر  وعاصرها  ومُعتصِرها   وشاربها   وساقيها   وحاملَها   والمحمولة إليه    وبائعها   ومشتريها   وآكل ثمنها \nإللي هو أي حاجة خاصة بالخمر من قريب ولا من بعيد محرمة وملعون صاحبها\nبعد ما جمعوا الخمر سَفَكوها كلها في طرقات المدينة يعني كبُّوها كلها في الأرض.\nلكن الصحابة ظهر عندهم مشكلة\nالناس إللي ماتوا، والناس إللي قُتلوا من المسلمين وكانوا بيشربوا خمر زي حمزة بن عبد المطلب،\nدول وضعهم إيه\nفأنزل الله تعالى:\n\"لَيْسَ عَلَى الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ جُنَاحٌ فِيمَا طَعِمُوا إِذَا مَا اتَّقَوا وَّآمَنُوا وَعَمِلُوا الصَّالِحَاتِ ثُمَّ اتَّقَوا وَّآمَنُوا ثُمَّ اتَّقَوا وَّأَحْسَنُوا ۗ وَاللَّهُ يُحِبُّ الْمُحْسِنِينَ\"\nيعني خلاص هم مكنش عندهم الحكم فربنا مش هيحاسبهم عليه، لكن إللي عايش وعرف الحكم يلزم أمر الله وأمر رسوله\n◇وعلى فكرة الخمر هي تقريبا المعصية الوحيدة إللي فيها  التحريم الشديد ده كله ، لأنها كما قال عنها عثمان بن عفان رضي الله عنه : \nاجتنبوا الخمر فهي أم الخبائث،\nوقال عنها رسول الله ﷺ:\nاجتنبوا الخمر فإنها مفتاح كل شر!\nيعني الشر كله بيأتي من ورائها، بسبب غياب العقل\nوفي قصة حكاها رسول الله ﷺ للصحابة توضح لهم خطورة شرب الخمر، \nقال لهم:\nكان في رجل معتزل الناس للعبادة، عابد يعني من الأمم إللي كانت قبلكم، فأحبته امرأة،\nفأرسلت له خادم من الخدم بتوعها يقول له احنا عايزينك للشهادة،\nفراح الرجل مع الخادم، وأدخله الخادم البيت فكان كل ما يعدي من باب في البيت الخادم يقفل الباب وراه بالمفتاح لحد ما وصل لامرأة شكلها جميل ومعاها غلام طفل صغير يعني، وكان جنبها زي زجاجة خمر،\nفقالت له:\nأنا لم أدعوك للشهادة ولكن دعوتك عشان تقتل الغلام ده أو تقع علي《عايزاه يزني بها》 أو تشرب كأس من الخمر،\nولو رفضت هصوّت وهفضحك وسط الناس\nفلما شاف إن مفيش مفر من الموقف إللي هو فيه ده،\nلقى إن أهون حاجة من وجهة نظره إنه يشرب من الخمر،\nوفعلا شرب كأس من الخمر، فقال لها زيديني، يعني هاتي كمان كأس،\nوفضل يشرب لحد ما بقى سكران، فقتل الغلام وزنى بالمرأة\nفقال لهم رسول الله ﷺ بعد ما حكى لهم القصة:\nفاجتنبوا الخمر، فإن الإيمان وإدمان الخمر لا يجتمعان في صدر رجل أبدا، وليوشكن أحدهما أن يخرج صاحبه\nيعني إما مؤمن وإما مدمن خمر \nوالوعيد في شرب الخمر شديد جدا،\nيعني إللي بيشرب الخمر ربنا لا يقبل منه صلاة أربعين يوم إذا لم يتب منها\nومش معنى إنها لا تُقبل منه، إنه يترك الصلاة\nلأ، ده يجب عليه الصلاة عشان يُسقط الفرض من عليه،\nلكن الكلام في القبول يعني ملوش ثواب على الصلاة كنوع من العقاب على ذنب شرب الخمر،\nوزي ما قلنا لا يُقبل لمن لم يتب، أما إللي شربها وتاب خلاص ربنا يقبل منه التوبة و الصلاة عادي،\nأما إللي يشرب الخمر من المسلمين ويموت من غير توبة، فهو مات على كبيرة من الكبائر،\nفهنا حكمه إلى الله، لو شاء الله عذبه ولو شاء غفر له،\nولو دخل الجنة بمشيئة الله، فهو إما يُحرم من الشرب من خمر الجنة إلى الأبد،\nأو إنه مُعرّض للحرمان من خمر الجنة لفترة مؤقتة،\nوظاهر حديث رسول الله ﷺ إن شارب الخمر في الدنيا هيتحرم منها للأبد في الجنة،\nيقول رسول الله ﷺ:\n\"مَنْ مَاتَ مِنْ أُمَّتِي وَهُوَ يَشْرَبُ الْخَمْرَ، حَرَّمَ اللهُ عَلَيْهِ شُرْبَهَا فِي الْجَنَّةِ\"\n☆طبعا حد ممكن يسأل، طيب الجنة مفيهاش حرمان وربنا قال:\n\"وَفِيهَا مَا تَشْتَهِيهِ الْأَنْفُسُ وَتَلَذُّ الْأَعْيُنُ وَأَنْتُمْ فِيهَا خَالِدُونَ\"\nفإزاي بقى شارب الخمر هيُحرم منها وكمان الحرمان نوع من أنواع الألم والعذاب، والجنة مفيهاش لا ألم ولا عذاب\nبكل بساطة، ربنا هينزع من قلبه اشتهاء الخمر، يعني مش هيبقى عايز يشرب خمر ومش هيكون حاببها ولا هتيجي على باله أصلا،\nلكن نعيمه هيبقى ناقص وهتفوته لذة عظيمة، ونقصان النعيم مش من العذاب لأن معروف إن أهل الجنة درجات وإللي بيتحرم من الدرجات العالية في الجنة لا يحزن وبيكون راضي باللي ربنا أعطاه له\nأما بقى إللي بيشرب الخمر وهو مُستحل لها، يعني يقول الخمر أصلا مش حرام وعادي إننا نشربها ومات على كده،\nفهو كافر لا يدخل الجنة أصلا، عافانا الله وإياكم\n《للتفصيل أكثر في موضوع الخمر، هتلاقوا  في موقع الإسلام سؤال وجواب\nرسول الله ﷺ مستمر في تربية الصحابة تربية إيمانية من خلال القصص، \nفإن شاء الله المرة الجاية هنحكي عن بعض القصص إللي رسول الله ﷺ حكاها للصحابة، قبل مانتكلم عن رد فعل العرب من المشركين على إللي حصل للمسلمين في غزوة أحد\n♡"}]);
